/* Conținutul caietului de practică – generat automat. */
window.CAIET = {"titlu":"Proiectare CAD în Tinkercad și imprimare 3D","subtitlu":"Piesele printate ale roverului FM-R2","scoala":"Liceul Tehnologic „Lazăr Edeleanu” Năvodari · Catedra Mecanică","clasa":"Clasa a IX-a E","an":"2026–2027","profesor":"prof. ing. Adrian-Mircea Beldugan","regulaDeAur":"Desenul tehnic dă cota la axa găurii. Tinkercad măsoară de la riglă până la marginea formei. Deci: margine = axă − Ø/2.","despre":"Nu lucrezi pe exerciții inventate: modelezi, una câte una, toate piesele din plastic ale roverului FM-R2, roverul clasei din proiectul eTwinning FutureMakers. Șasiul este din aluminiu. Restul se imprimă: roțile, suporturile motoarelor, carcasele modulelor, șinele de prindere, caseta acumulatorului. În Tinkercad folosești aceleași cote, vederi și toleranțe ca la desenul tehnic, dar construiești piesa din forme simple: cutii, cilindri, conuri și găuri.","etwinning":"Partenerii din Düzce (Turcia) primesc fișierele STL și fotografiile pieselor. Fiecare echipă publică pe TwinSpace o piesă pe săptămână: o imagine, 3 propoziții și fișierul STL.","saptamani":[{"id":"S1","perioada":"02–04.12.2026","zile":"miercuri–vineri (30 noiembrie și 1 decembrie sunt zile libere)","ore":18,"ce":"Te familiarizezi cu Tinkercad și cu imprimanta 3D. Modelezi primele piese plate ale carcaselor (fețe și capace), le imprimi și le controlezi cu șublerul. La final, clasa are șablonul de ajustaje, care fixează diametrele găurilor pentru imprimanta noastră.","zileLucru":["2026-12-02","2026-12-03","2026-12-04"]},{"id":"S2","perioada":"15–19.02.2027","zile":"luni–vineri","ore":30,"ce":"Modelezi piese cu multe găuri repetate (plăci de montaj), lucrezi după o fișă tehnică (Arduino Mega) și construiești profiluri standardizate: șina Picatinny și cârligul DIN. Ultima zi: schița după model pentru fețele cu senzori.","zileLucru":["2027-02-15","2027-02-16","2027-02-17","2027-02-18","2027-02-19"]},{"id":"S3","perioada":"15–19.03.2027","zile":"luni–vineri","ore":30,"ce":"Treci la piese 3D „cu pereți”: carcasele A, B și C, cu stâlpi, bosaje, găuri orizontale „picătură” și fălci de prindere. Ziua a cincea: asamblezi digital și fizic un modul C complet.","zileLucru":["2027-03-15","2027-03-16","2027-03-17","2027-03-18","2027-03-19"]},{"id":"S4","perioada":"10–14.05.2027","zile":"luni–vineri","ore":30,"ce":"Modelezi sistemul de propulsie: butucul cu alezaj în D, roata fără aer cu spițe în arc (repetare polară) și suportul de motor. Ziua a cincea: asamblarea digitală a unei roți complete și controlul pieselor.","zileLucru":["2027-05-10","2027-05-11","2027-05-12","2027-05-13","2027-05-14"]},{"id":"S5","perioada":"31.05–04.06.2027","zile":"luni, miercuri–vineri (1 iunie este zi liberă)","ore":24,"ce":"Modelezi sistemul acumulatorului (casetă, locaș, zăvor cu arc), finalizezi fișa procesului de imprimare, montezi toate piesele pe șasiu și îți prezinți proiectul individual.","zileLucru":["2027-05-31","2027-06-02","2027-06-03","2027-06-04"]}],"lectii":[{"nr":1,"titlu":"Siguranța în laborator. Primul contact cu Tinkercad","sapt":"S1","data":"mi 02.12.2026","ore":3,"teme":"T1 · T2","piese":"33 Față C oarbă","scop":"Lucrezi în siguranță la calculator și lângă imprimanta 3D. Intri în clasa virtuală Tinkercad, te orientezi în spațiul 3D și modelezi prima piesă: fața oarbă a carcasei C.","stiu":["respect regulile SSM din laboratorul CAD și de la imprimanta 3D","intru în clasa Tinkercad cu codul clasei și porecla (nickname)","rotesc, deplasez și măresc vederea; așez o formă și îi dau dimensiuni exacte","export piesa în format STL"],"nevoie":["laptop cu mouse cu rotiță","codul clasei și porecla (de la profesor)","caietul, creion, riglă"],"casete":[{"titlu":"SSM","text":["Postura la calculator: spatele drept, ecranul la nivelul ochilor, pauză scurtă la fiecare oră. Nu atingeți duza sau masa imprimantei: duza ajunge la 240 °C, masa la 80 °C. Nu mâncați și nu beți lângă calculatoare."]}],"comenzi":[["Intrare în clasă","tinkercad.com → Log in → Students, join a Class → codul clasei → Join with Nickname"],["Design nou","Create → 3D Design; redenumiți: FMR2_33_fata_oarba_Nume"],["Navigare","rotire: buton dreapta mouse · deplasare: Shift + buton dreapta (sau rotiță apăsată) · zoom: rotiță · F = încadrează selecția"],["Cub de vedere","click pe fețele cubului din stânga-sus: Front, Top, Right"],["Dimensiuni exacte","click pe o cotă albă de pe formă și tastați valoarea, apoi Enter"],["Pasul grilei","Snap Grid (dreapta-jos) = 0,1 mm"],["Export","Export → .STL"]],"pasi":["Citiți și semnați fișa de instruire SSM de la începutul caietului.","Intrați în clasa Tinkercad cu codul primit. Notați codul clasei pe prima pagină a caietului (porecla rămâne secretă, ca o parolă).","Creați un design nou și redenumiți-l după regula clasei: FMR2_33_fata_oarba_Nume.","Setați Snap Grid la 0,1 mm. Așezați o Cutie (Box) pe planul de lucru.","Dați cutiei dimensiunile 68,4 (X) × 43,7 (Y) × 2 (Z). Piesa se modelează culcată, exact cum se imprimă.","Verificați din vederile Front și Top. Comparați cu schița de pe fișa piesei.","Exportați piesa ca STL și salvați fișierul în dosarul echipei: Echipa_X/S1/.","Exercițiu de navigare: așezați 5 forme diferite (cilindru, con, sferă, tub, text), dați-le dimensiuni din tabelul profesorului, apoi ștergeți-le."],"fise":[{"nr":"33","nume":"Față C oarbă","info":"2 buc. pe rover · lecția 1","cote":[{"nr":"1","cota":"Lungime (în canale)","nominal":"68,4","tol":"±0,1"},{"nr":"2","cota":"Înălțime","nominal":"43,7","tol":"±0,1"},{"nr":"3","cota":"Grosime","nominal":"2,0","tol":"±0,1"}],"parametri":["PETG, strat 0,2","plat","3 pereți / 20%","nu","0,3 h / 6 g"],"img":"img/piese/33.png"}],"control":["Numele designului respectă regula clasei","Dimensiunile sunt exact 68,4 × 43,7 × 2","Fișierul STL este salvat în dosarul echipei"],"reflectie":"De ce modelăm piesa culcată, în poziția în care se imprimă?","iso":"2026-12-02","quiz":[{"q":"Ce valoare are pasul grilei (Snap Grid) la orele noastre?","o":["1 mm","0,1 mm","0,5 mm","0,25 mm"],"a":1,"e":"Cotele pieselor au zecimale (68,4; 43,7), deci lucrăm cu pasul de 0,1 mm."},{"q":"Ce dimensiuni are fața C oarbă (piesa 33)?","o":["70 × 50 × 2,5","68,4 × 43,7 × 2","68 × 44 × 2","43,7 × 68,4 × 2,5"],"a":1,"e":"Fișa piesei 33: lungime 68,4, înălțime 43,7, grosime 2,0, fiecare ±0,1."},{"q":"De ce modelăm piesa culcată?","o":["Pentru că Tinkercad nu permite piese în picioare","Așa se imprimă: fața care stă pe masă este jos","Ca să arate mai bine în vederi","Ca fișierul STL să fie mai mic"],"a":1,"e":"Piesa se modelează în poziția de imprimare, cu fața care stă pe masă jos."},{"q":"Ce temperatură atinge duza imprimantei?","o":["80 °C","120 °C","240 °C","400 °C"],"a":2,"e":"Duza ajunge la 240 °C, masa la 80 °C. Nu le atingem în timpul lucrului și imediat după."}]},{"nr":2,"titlu":"Găuri, aliniere, riglă. Fața pentru buzzer și capacul C simplu","sapt":"S1","data":"mi 02.12.2026","ore":3,"teme":"T2","piese":"32 Față C pentru buzzer, 24 Capac C simplu","scop":"Înveți să faci găuri și să le poziționezi exact cu Rigla și cu Alinierea. Modelezi fața pentru buzzer și capacul simplu al carcasei C.","stiu":["transform o formă în gaură (Hole) și o grupez cu piesa","poziționez o gaură față de colțul piesei cu Rigla","centrez o gaură cu Alinierea (L)","transform cotele din desenul tehnic (axe de găuri) în poziții Tinkercad"],"nevoie":["designul de la lecția 1","fișele pieselor 32 și 24"],"casete":[{"titlu":"SSM","text":["Cablurile laptopurilor nu trec prin zona de circulație. Prelungitoarele nu se încarcă peste puterea înscrisă."]}],"comenzi":[["Gaură","selectați forma → Hole în panoul Shape"],["Grupare","selectați tot → Ctrl + G; degrupare: Ctrl + Shift + G"],["Rigla","R, apoi click în colțul piesei; cotele arată distanța de la riglă la marginea formei"],["Aliniere","selectați piesa și gaura → L → click pe punctele de mijloc"],["Copiere","Ctrl + C / Ctrl + V; dublură pe loc: Ctrl + D"]],"pasi":["Regula riglei: Tinkercad măsoară de la riglă până la marginea formei, nu până la axă. În desen avem axa găurii. Deci: margine = axă − Ø/2. Exemplu: gaura Ø3,4 cu axa la 5,4 de margine are marginea la 5,4 − 1,7 = 3,7.","Fața pentru buzzer (32): copiați fața oarbă. Adăugați un Cilindru Ø12, înalt de 4 mm, și transformați-l în gaură.","Selectați placa și gaura, apăsați L și centrați pe X și pe Y. Grupați (Ctrl + G). Verificați: gaura e la 34,2 de margine pe X și la 21,85 pe Y.","Capacul simplu C (24): Cutie 70 × 50 × 2,5. Puneți rigla în colțul stânga-față.","Două cilindre Ø3,4 (laturi: 32), înalte de 5 mm, ca găuri. Axele lor sunt la X = 5,4 și X = 64,6, ambele la Y = 5,4. Calculați marginile și tastați-le.","Grupați. Verificați entraxa găurilor: 64,6 − 5,4 = 59,2 mm.","Exportați ambele piese ca STL."],"fise":[{"nr":"32","nume":"Față C pentru buzzer","info":"1 buc. pe rover · lecția 2","cote":[{"nr":"1","cota":"Placă","nominal":"68,4 × 43,7 × 2","tol":"±0,1"},{"nr":"2","cota":"Gaură buzzer (centrată)","nominal":"Ø12","tol":"±0,15"}],"parametri":["PETG, strat 0,2","plat","3 pereți / 20%","nu","0,3 h / 6 g"],"img":"img/piese/32.png"},{"nr":"24","nume":"Capac C simplu","info":"2 buc. pe rover · lecția 2","cote":[{"nr":"1","cota":"Lungime × lățime × grosime","nominal":"70 × 50 × 2,5","tol":"±0,2"},{"nr":"2","cota":"Găuri (2×) · entraxe","nominal":"Ø3,4 · 59,2","tol":"±0,15"},{"nr":"3","cota":"Poziția găurilor de la margini","nominal":"5,4 / 5,4","tol":"±0,2"}],"parametri":["PETG, strat 0,2","plat","3 pereți / 20%","nu","0,4 h / 9 g"],"img":"img/piese/24.png"}],"control":["Gaura Ø12 este centrată (34,2 / 21,85)","Găurile capacului au axele la 5,4 de margini","Fiecare piesă e un singur grup"],"reflectie":"Ce diferență este între cota de la riglă (la margine) și cota din desenul tehnic (la axă)? Dați un exemplu cu numere.","iso":"2026-12-02","quiz":[{"q":"O gaură Ø3,4 are axa la 5,4 mm de margine. Ce cotă tastezi în Tinkercad (de la riglă la marginea găurii)?","o":["5,4","3,7","7,1","1,7"],"a":1,"e":"margine = axă − Ø/2 = 5,4 − 1,7 = 3,7."},{"q":"Ce tastă pornește Alinierea?","o":["A","R","L","G"],"a":2,"e":"L = aliniere. R = riglă, Ctrl + G = grupare."},{"q":"Găurile capacului C simplu au axele la X = 5,4 și X = 64,6. Cât este entraxa?","o":["64,6","59,2","70","55,8"],"a":1,"e":"64,6 − 5,4 = 59,2 mm."},{"q":"Cum transformi un cilindru în gaură?","o":["Ctrl + G","Selectezi forma → Hole","Tasta Delete","Tasta M"],"a":1,"e":"Hole din panoul Shape; apoi grupezi gaura cu piesa."}]},{"nr":3,"titlu":"Capacele carcaselor A și B: colțuri rotunjite, lamaje, fante repetate","sapt":"S1","data":"jo 03.12.2026","ore":3,"teme":"T2","piese":"11 Capac A, 13 Capac B","scop":"Modelezi capacele carcaselor de pe șina DIN. Folosești rotunjirea colțurilor (Radius), faci lamaje pentru capetele șuruburilor și repeți fantele cu Duplicare și repetare.","stiu":["rotunjesc colțurile unei cutii cu parametrul Radius","fac un lamaj (gaură în trepte)","repet o formă la pas constant cu Ctrl + D","refolosesc un model pentru o piesă asemănătoare"],"nevoie":["fișele pieselor 11 și 13"],"casete":[{"titlu":"SSM","text":["La 45 de minute de lucru, 5 minute de pauză pentru ochi: priviți un punct îndepărtat."]}],"comenzi":[["Raza colțurilor","Box → Radius = 3, Steps = 10"],["Duplicare și repetare","selectați → Ctrl + D → mutați copia → apăsați Ctrl + D din nou: Tinkercad repetă aceeași mutare"],["Mutare precisă","săgeți = un pas de grilă; Shift + săgeată = 10 pași; Ctrl + săgeată sus/jos = pe Z"]],"pasi":["Capacul A (11): Cutie 86 × 120 × 2,5, Radius = 3.","Găurile Ø3,4 (4×) au axele la 5,9 mm de ambele margini (marginea găurii la 4,2). Entraxe: 74,2 × 108,2.","Lamajul: peste fiecare gaură, un cilindru-gaură Ø6, înalt de 1,6 mm, așezat cu fața de sus la nivelul capacului (Z de la 0,9 la 2,5). Capul șurubului M3 intră în lamaj.","Fantele: o cutie-gaură 56 × 3 × 5, centrată pe X (de la X = 15 la X = 71), cu axa la Y = 24. Ctrl + D, mutați 12 mm pe Y; apoi încă 5 × Ctrl + D. Rezultă 7 fante, cu axele la Y = 24, 36, … 96.","Grupați și verificați cu rigla prima și ultima fantă.","Capacul B (13): copiați capacul A și îl modificați: lungimea 43, găurile la 5,9 de margini (entraxe 31,2), fantele de 13 mm (de la X = 15 la X = 28).","Observați: modificarea unei piese existente durează câteva minute. Modelarea de la zero durează o oră."],"fise":[{"nr":"11","nume":"Capac A","info":"3 buc. pe rover · lecția 3","cote":[{"nr":"1","cota":"Lungime × lățime × grosime","nominal":"86 × 120 × 2,5 · R3","tol":"±0,2"},{"nr":"2","cota":"Găuri șuruburi (4×)","nominal":"Ø3,4 · entraxe 74,2 × 108,2","tol":"±0,15"},{"nr":"3","cota":"Lamaj (pentru capul M3)","nominal":"Ø6 × 1,6","tol":"±0,15"},{"nr":"4","cota":"Fante de aerisire (7×)","nominal":"56 × 3 · pas 12","tol":"±0,2"}],"parametri":["PETG, strat 0,2","plat, lamajele în sus","3 pereți / 20%","nu","1,1 h / 24 g"],"img":"img/piese/11.png"},{"nr":"13","nume":"Capac B","info":"2 buc. pe rover · lecția 3","cote":[{"nr":"1","cota":"Lungime × lățime × grosime","nominal":"43 × 120 × 2,5 · R3","tol":"±0,2"},{"nr":"2","cota":"Găuri șuruburi (4×)","nominal":"Ø3,4 · entraxe 31,2 × 108,2","tol":"±0,15"},{"nr":"3","cota":"Lamaj","nominal":"Ø6 × 1,6","tol":"±0,15"},{"nr":"4","cota":"Fante de aerisire (7×)","nominal":"13 × 3 · pas 12","tol":"±0,2"}],"parametri":["PETG, strat 0,2","plat, lamajele în sus","3 pereți / 20%","nu","0,6 h / 13 g"],"img":"img/piese/13.png"}],"control":["Colțuri R3","Lamaje Ø6 × 1,6 pe partea de sus","7 fante la pas 12, simetrice","Capacul B are aceleași găuri la 5,9 de margini"],"reflectie":"De ce e util ca toate capacele să aibă găurile la aceeași distanță (5,9 mm) de margine?","iso":"2026-12-03","quiz":[{"q":"Ce face Ctrl + D apăsat a doua oară, după ce ai mutat copia?","o":["Șterge copia","Repetă aceeași mutare","Grupează formele","Oglindește forma"],"a":1,"e":"Duplicare și repetare: Tinkercad reține mutarea și o repetă la fiecare Ctrl + D."},{"q":"Ce este un lamaj?","o":["O fantă de aerisire","O gaură în trepte pentru capul șurubului","Un colț rotunjit","O gaură conică"],"a":1,"e":"Lamajul Ø6 × 1,6 primește capul șurubului M3."},{"q":"Fantele capacului A au axele la Y = 24, 36 … 96. Câte fante sunt?","o":["6","7","8","12"],"a":1,"e":"(96 − 24) / 12 + 1 = 7 fante, la pas 12."},{"q":"De ce facem capacul B pornind de la capacul A?","o":["Pentru că e obligatoriu în Tinkercad","Modificarea durează minute, modelarea de la zero o oră","Ca să aibă aceeași lungime","Ca să nu mai fie nevoie de fișa piesei"],"a":1,"e":"Refolosirea unui model existent economisește timp și păstrează aceleași găuri la 5,9 mm."}]},{"nr":4,"titlu":"Imprimanta 3D și feliatorul (slicer). Primele imprimări","sapt":"S1","data":"jo 03.12.2026","ore":3,"teme":"T3","piese":"—","scop":"Înveți cum funcționează o imprimantă FDM. Pregătești în feliator (slicer) piesele din lecțiile 1–3, le imprimi și urmărești primul strat.","stiu":["numesc părțile imprimantei: duză, extruder, masă, axe, filament","aleg materialul potrivit: PLA, PETG sau TPU","setez în feliator: înălțimea stratului, pereții, umplerea, suporturile, orientarea","verific primul strat și opresc imprimarea dacă apare un defect"],"nevoie":["fișierele STL ale echipei","feliatorul instalat (PrusaSlicer, Cura sau Bambu Studio, după imprimanta liceului)","filament PETG, spatulă, lipici pentru masă"],"casete":[{"titlu":"SSM","text":["Imprimanta lucrează la 240 °C (duza) și 80 °C (masa). Nu atingeți duza sau masa în timpul lucrului. Piesa se scoate doar după ce masa se răcește sub 35 °C. Spatula se mișcă dinspre corp spre exterior. Aerisiți încăperea; nu stați aplecat deasupra imprimantei."]},{"titlu":"CE VERIFICI LA PRIMUL STRAT","text":["liniile sunt turtite și lipite între ele (nu rotunde, nu cu goluri);","colțurile nu se ridică;","nu apar fire trase sau bucăți lipite de duză.","Dacă vezi un defect: opriți, curățați masa, verificați nivelarea, porniți din nou."]}],"comenzi":[["Import STL în feliator","File → Import"],["Așezare pe față","Place on face / Lay on face"],["Previzualizare straturi","Slice → glisorul de straturi"]],"pasi":["Demonstrația profesorului: ciclul de imprimare (încălzire, nivelare, primul strat, răcire, scoaterea piesei).","Completați tabelul de materiale din anexa B: temperaturi, unde se folosește fiecare material, pentru ce piese ale roverului.","Importați în feliator piesele 33, 32, 24, 11 și 13. Setările clasei: PETG, strat 0,2 mm, 3 pereți, umplere 20%, fără suporturi.","Așezați piesele pe masă. Notați în tabelul de mai jos timpul și masa estimate de feliator.","Trimiteți imprimarea și urmăriți primul strat: liniile trebuie să fie lipite între ele, nu rotunde și nici transparente.","Lucru în paralel, cât se imprimă: fișa de control pentru lecția 5."],"fise":[],"control":["Setările clasei sunt aplicate","Primul strat a fost verificat","Timpul și masa sunt notate"],"reflectie":"Ce s-ar întâmpla dacă ați imprima capacul A în picioare (pe muchia de 2,5 mm)? Gândiți-vă la timp, rezistență și aderență.","iso":"2026-12-03","quiz":[{"q":"Care sunt setările clasei în feliator?","o":["PLA, strat 0,1, 5 pereți, 100%","PETG, strat 0,2, 3 pereți, 20%, fără suporturi","PETG, strat 0,3, 2 pereți, 0%","TPU, strat 0,2, 3 pereți, cu suporturi"],"a":1,"e":"Setările clasei: PETG, strat 0,2 mm, 3 pereți, umplere 20%, fără suporturi."},{"q":"Când scoți piesa de pe masa imprimantei?","o":["Imediat după terminare","Când masa s-a răcit sub 35 °C","Când masa are 80 °C","În timpul imprimării, dacă e gata partea de jos"],"a":1,"e":"Piesa se scoate după ce masa se răcește sub 35 °C; spatula se mișcă dinspre corp spre exterior."},{"q":"Cum arată un prim strat bun?","o":["Linii rotunde, separate","Linii turtite și lipite între ele","Linii transparente","Colțuri ridicate"],"a":1,"e":"Liniile trebuie să fie turtite și lipite, fără goluri, iar colțurile nu se ridică."},{"q":"Ai observat un defect la primul strat. Ce faci?","o":["Las imprimarea să continue","Opresc, curăț masa, verific nivelarea, pornesc din nou","Măresc temperatura duzei cu 50 °C","Apăs piesa cu degetul"],"a":1,"e":"La defect: oprim, curățăm masa, verificăm nivelarea și pornim din nou."}]},{"nr":5,"titlu":"Controlul pieselor imprimate. Șablonul de ajustaje al clasei","sapt":"S1","data":"vi 04.12.2026","ore":6,"teme":"T3 · T5","piese":"E1","scop":"Măsori piesele imprimate și calculezi abaterile. Modelezi și imprimi șablonul de ajustaje. Cu el, clasa alege diametrele găurilor care se potrivesc pe imprimanta noastră.","stiu":["măsor cu șublerul și calculez abaterea: valoare măsurată − cotă nominală","decid dacă o piesă este conformă cu toleranța","adaug text 3D pe o piesă","aleg diametrele găurilor după încercări, nu după „cum pare”"],"nevoie":["piesele imprimate în lecția 4","șubler 0,05 mm","șuruburi M3 și M4, inserții filetate M3 și","M4, arborele unui motor NEMA 17"],"casete":[{"titlu":"SSM","text":["Inserțiile se montează doar de profesor sau sub supravegherea lui: letcon la 230–240 °C, mănuși și ochelari de protecție."]},{"titlu":"DE CE UN ȘABLON?","text":["Fiecare imprimantă scoate găurile puțin mai mici decât în model: plasticul se strânge la răcire, iar cercul e făcut din segmente. Nu ghicim corecția. O măsurăm o dată, pe o piesă de probă, și o scriem în Standardele clasei."]}],"comenzi":[["Text 3D","Basic Shapes → Text: înălțime 4, grosime 0,6, font Sans"],["Gaură cu formă de D","cilindru plin − cutie = D; apoi grupați și faceți gaură"],["Blocare","Ctrl + L, ca să nu mutați din greșeală"]],"pasi":["Controlul pieselor: măsurați fiecare cotă din fișele pieselor 33, 32, 24, 11 și 13. Completați coloanele „Imprimat”, „Abatere” și „Conform”.","Șablonul E1: Cutie 110 × 36 × 6, Radius 2.","Rândul 1 (Y = 10): găuri de trecere M3 Ø3,0 / 3,2 / 3,4 / 3,6, apoi găuri pentru inserții M3 Ø3,8 / 4,0 / 4,2. Axele sunt la X = 8, 21, 34 … (pas 13).","Rândul 2 (Y = 26): găuri pentru inserții M4 Ø5,4 / 5,6 / 5,8, apoi găuri în D pentru arborele motorului Ø5,0 / 5,2 / 5,4 (planul la 2,1 de axă). Pas 13.","Gaura în D: cilindru Ø5,2 (plin) + cutie 6 × 6 așezată cu marginea la 2,1 de axă. Grupați, apoi transformați grupul în gaură.","Sub fiecare gaură, text cu diametrul (ex. „3.4”), adâncit 0,6 mm în piesă (textul ca gaură).","Imprimați șablonul. Încercați: șurubul M3 trece liber? inserția intră cu letconul și ține? arborele intră fără joc?","Decizia clasei: încercuiți în tabelul „Standardele clasei” valorile alese. Dacă imprimanta voastră dă alte valori decât Ø3,4 / 4,0 / 5,6 / 5,2, notați-le: le folosiți în toate lecțiile următoare."],"fise":[{"nr":"E1","nume":"Șablon de ajustaje al clasei","info":"1 buc. pe echipă · nu face parte din rover","cote":[],"parametri":["PETG, strat 0,2","plat","3 pereți / 20%","nu","—"],"sablon":true}],"control":["Toate piesele din S1 sunt măsurate","Șablonul este imprimat și încercat","Standardele clasei sunt completate"],"reflectie":"Ce ați face dacă toate găurile ies cu 0,2 mm mai mici decât în model?","iso":"2026-12-04","quiz":[{"q":"Cum se calculează abaterea?","o":["nominal − măsurat","măsurat − nominal","măsurat ÷ nominal","toleranță − măsurat"],"a":1,"e":"Abaterea = cota măsurată − cota nominală."},{"q":"Cota nominală 70 ± 0,2. Ai măsurat 69,75. Piesa e conformă?","o":["Da, e aproape de 70","Nu: abaterea −0,25 iese din toleranța ±0,2","Da: abaterea e +0,25","Nu se poate decide"],"a":1,"e":"69,75 − 70 = −0,25; |−0,25| > 0,2, deci NU e conformă."},{"q":"De ce ies găurile imprimate mai mici decât în model?","o":["Pentru că șublerul nu e precis","Plasticul se strânge la răcire, iar cercul e făcut din segmente","Pentru că Tinkercad rotunjește cotele","Din cauza umplerii de 20%"],"a":1,"e":"De aceea măsurăm o dată corecția pe șablonul E1 și o scriem în Standardele clasei."},{"q":"Ce diametru nominal are gaura pentru inserția M3?","o":["Ø3,4","Ø4,0","Ø5,6","Ø2,5"],"a":1,"e":"Inserția M3 (Ø ext. 4,6) intră în gaura Ø4,0; Ø3,4 este gaura de trecere M3."}]},{"nr":6,"titlu":"Plăci de montaj cu grilă de găuri","sapt":"S2","data":"lu 15.02.2027","ore":6,"teme":"T4","piese":"16 Placă de montaj B – grilă, 14 Placă de montaj A – grilă","scop":"Modelezi plăcile pe care se prind modulele electronice în carcasele A și B. Repeți găurile pe două direcții (grilă) și le verifici cu rigla.","stiu":["repet o gaură pe un rând, apoi rândul pe coloane (matrice)","verific o grilă prin prima, ultima și o gaură din mijloc","organizez un model cu multe forme: grupare pe etape"],"nevoie":["fișele pieselor 16 și 14","standardele clasei (gaura de trecere M3)"],"casete":[{"titlu":"SSM","text":["Prizele multiple nu se acoperă cu genți sau haine (se încălzesc)."]}],"comenzi":[["Matrice de găuri","un rând cu Ctrl + D → grupați rândul → Ctrl + D pe Y"],["Ascundere","Ctrl + H; afișare: Ctrl + Shift + H"],["Selecție multiplă","Shift + click, sau trageți un dreptunghi"]],"pasi":["Placa B (16): Cutie 37,2 × 100,2 × 2,5. Rigla în colțul stânga-față.","Găurile de prindere Ø3,4 (4×): axele la X = 9,1 și 28,1, Y = 4,1 și 96,1 (entraxe 19 × 92).","Grila Ø3,2 (laturi 16): prima gaură cu axa la X = 8,6, Y = 10,1. Ctrl + D de 2 ori pe X, pas 10. Rezultă rândul: 8,6 / 18,6 / 28,6.","Grupați rândul. Ctrl + D de 8 ori pe Y, pas 10. Ultimul rând are axa la Y = 90,1. Total: 27 de găuri.","Grupați tot. Verificați 3 găuri cu rigla: prima, ultima și una din mijloc.","Placa A (14): Cutie 80,2 × 100,2 × 2,5. Găurile de prindere la X = 9,1 și 71,1, Y = 4,1 și 96,1 (entraxe 62 × 92).","Grila: 7 coloane (X = 10,1 … 70,1) × 9 rânduri (Y = 10,1 … 90,1) = 63 de găuri.","Exportați. În feliator: cele 2 plăci B și 2 plăci A pe aceeași masă."],"fise":[{"nr":"16","nume":"Placă de montaj B – grilă","info":"2 buc. pe rover · lecția 6","cote":[{"nr":"1","cota":"Lungime × lățime × grosime","nominal":"37,2 × 100,2 × 2,5","tol":"±0,2"},{"nr":"2","cota":"Găuri de prindere (4×)","nominal":"Ø3,4 · entraxe 19 × 92","tol":"±0,15"},{"nr":"3","cota":"Grilă de găuri (3 × 9 = 27)","nominal":"Ø3,2 · pas 10","tol":"±0,15"}],"parametri":["PETG, strat 0,2","plat","3 pereți / 20%","nu","0,4 h / 9 g"],"img":"img/piese/16.png"},{"nr":"14","nume":"Placă de montaj A – grilă","info":"2 buc. pe rover · lecția 6","cote":[{"nr":"1","cota":"Lungime × lățime × grosime","nominal":"80,2 × 100,2 × 2,5","tol":"±0,2"},{"nr":"2","cota":"Găuri de prindere (4×)","nominal":"Ø3,4 · entraxe 62 × 92","tol":"±0,15"},{"nr":"3","cota":"Grilă de găuri (7 × 9 = 63)","nominal":"Ø3,2 · pas 10","tol":"±0,15"},{"nr":"4","cota":"Prima gaură a grilei de la colț","nominal":"10,1 / 10,1","tol":"±0,2"}],"parametri":["PETG, strat 0,2","plat","3 pereți / 20%","nu","0,9 h / 20 g"],"img":"img/piese/14.png"}],"control":["27 și 63 de găuri, fără gaură lipsă sau dublă","Grila e simetrică față de axa plăcii","Găurile de prindere nu se suprapun cu grila"],"reflectie":"Placa are 63 de găuri. Câte operații Ctrl + D ați făcut? Cum ați verificat că nu lipsește nicio gaură?","iso":"2027-02-15","quiz":[{"q":"Grila plăcii A are 7 coloane și 9 rânduri. Câte găuri are?","o":["56","63","72","27"],"a":1,"e":"7 × 9 = 63 de găuri."},{"q":"Cum verifici rapid o grilă de găuri?","o":["Măsori toate găurile","Verifici prima, ultima și o gaură din mijloc","Verifici doar prima gaură","Te uiți din vederea izometrică"],"a":1,"e":"Dacă prima, ultima și una din mijloc sunt la locul lor, pasul este corect."},{"q":"Ce pas are grila de găuri Ø3,2?","o":["9,1 mm","10 mm","12 mm","5 mm"],"a":1,"e":"Grila are pasul de 10 mm pe ambele direcții."}]},{"nr":7,"titlu":"Lucrul după fișa tehnică: placa pentru Arduino Mega. Fața ventilată","sapt":"S2","data":"ma 16.02.2027","ore":6,"teme":"T4","piese":"15 Placă de montaj A – Arduino Mega, 31 Față C ventilată","scop":"Citești o fișă tehnică (datasheet) și transformi coordonatele găurilor plăcii Arduino Mega în coordonatele piesei tale. Modelezi stâlpii de prindere și fața ventilată pentru senzorii de mediu.","stiu":["extrag cote dintr-o fișă tehnică în inch și mm","schimb sistemul de coordonate (rotire cu 90° și translație)","modelez stâlpi (cilindru plin + cilindru gaură)"],"nevoie":["fișa tehnică Arduino Mega 2560 (desenul cu găuri)","o placă Mega pentru verificare","fișele pieselor 15 și 31"],"casete":[{"titlu":"SSM","text":["Plăcile electronice se țin de margini. Nu atingeți pinii (descărcări electrostatice)."]}],"comenzi":[["Grupuri cu culori","Shape → bifați Multicolor ca să vedeți piesele componente"],["Notă","N = notă pe planul de lucru (ex. „stâlp 1”)"]],"pasi":["În fișa tehnică, găurile Mega sunt date de la colțul plăcii (x pe lungimea de 101,6, y pe lățimea de 53,3). Pe placa noastră, Mega stă rotită cu 90°.","Formula de transformare (coordonatele de pe placa noastră, de la colț): X = 13,43 + yfișă și Y = xfișă − 0,7. Completați tabelul de transformare de pe fișa piesei.","Copiați placa A și scoateți grila. Păstrați cele 4 găuri de prindere.","Stâlp: cilindru Ø6,4 × 6, așezat pe placă (Z de la 2,5 la 8,5). Gaură Ø2,5, de la Z = 3 până sus. Grupați stâlpul, apoi repetați-l în cele 6 poziții calculate.","Verificare fizică: imprimați întâi doar o placă subțire (1 mm), doar cu găurile. Așezați Mega peste ea: toate cele 6 găuri trebuie să se potrivească.","Fața ventilată (31): fața oarbă + 9 fante-gaură 2,5 × 31,7, de la Y = 6 la Y = 37,7. Prima fantă are marginea la X = 6,95; pasul este 6,5."],"fise":[{"nr":"15","nume":"Placă de montaj A – Arduino Mega","info":"1 buc. pe rover · lecția 7","cote":[{"nr":"1","cota":"Placa (L × l × g)","nominal":"80,2 × 100,2 × 2,5","tol":"±0,2"},{"nr":"2","cota":"Găuri de prindere (4×)","nominal":"Ø3,4 · entraxe 62 × 92","tol":"±0,15"},{"nr":"3","cota":"Stâlpi Mega (6×)","nominal":"Ø6,4 × 6","tol":"±0,2"},{"nr":"4","cota":"Găuri în stâlpi (autofiletant M3)","nominal":"Ø2,5 × 5,5","tol":"±0,1"},{"nr":"5","cota":"Stâlpii 1 și 6 (verificare entraxe)","nominal":"82,55","tol":"±0,15"}],"parametri":["PETG, strat 0,2","plat, stâlpii în sus","3 pereți / 20%","nu","1,0 h / 23 g"],"transformare":{"formula":"X = 13,43 + y fișă   ·   Y = x fișă − 0,7","randuri":[["1","13,97","2,54","15,97","13,27"],["2","15,24","50,80","64,23","14,54"],["3","66,04","7,62","21,05","65,34"],["4","66,04","35,56","48,99","65,34"],["5","90,17","50,80","64,23","89,47"],["6","96,52","2,54","15,97","95,82"]]},"img":"img/piese/15.png"},{"nr":"31","nume":"Față C ventilată (senzori de mediu)","info":"1 buc. pe rover · lecția 7","cote":[{"nr":"1","cota":"Placă","nominal":"68,4 × 43,7 × 2","tol":"±0,1"},{"nr":"2","cota":"Fante (9×)","nominal":"2,5 × 31,7 · pas 6,5","tol":"±0,15"},{"nr":"3","cota":"Prima fantă de la margine","nominal":"6,95","tol":"±0,2"}],"parametri":["PETG, strat 0,2","plat","3 pereți / 20%","nu","0,2 h / 5 g"],"img":"img/piese/31.png"}],"control":["Tabelul de transformare este completat","Proba de 1 mm se potrivește pe placa Mega","Cele 9 fante sunt simetrice"],"reflectie":"De ce am imprimat întâi o probă subțire? Cât timp și cât material ați economisit?","iso":"2027-02-16","quiz":[{"q":"Care este formula pentru X pe placa noastră?","o":["X = x fișă − 0,7","X = 13,43 + y fișă","X = 13,43 − y fișă","X = x fișă + 13,43"],"a":1,"e":"Mega este rotită cu 90°: X = 13,43 + y fișă și Y = x fișă − 0,7."},{"q":"De ce imprimăm întâi o probă subțire de 1 mm?","o":["Ca să testăm culoarea","Verificăm potrivirea găurilor cu puțin timp și material","Pentru că placa reală e de 1 mm","Ca să încălzim imprimanta"],"a":1,"e":"O probă subțire arată dacă toate cele 6 găuri se potrivesc, fără să pierdem o oră de imprimare."},{"q":"Din ce forme se face un stâlp de prindere?","o":["Cutie plină + con","Cilindru plin Ø6,4 + cilindru-gaură Ø2,5","Tub + pană","Doi cilindri-gaură"],"a":1,"e":"Stâlp Ø6,4 × 6, cu gaură Ø2,5 pentru șurub autofiletant M3."}]},{"nr":8,"titlu":"Profil standardizat: șina Picatinny (MIL-STD-1913)","sapt":"S2","data":"mi 17.02.2027","ore":6,"teme":"T4","piese":"20 Șină Picatinny 150, 21 Șină Picatinny 70","scop":"Construiești un profil standardizat din forme simple (cutie și pătrate rotite la 45°). Repeți canalele la pasul standard de 10,01 mm. Faci găuri pentru șuruburi cu cap înecat.","stiu":["construiesc un profil din cutii și forme rotite","rotesc o formă la un unghi exact","fac gaură conică pentru cap înecat (con- gaură)","repet canale la pas zecimal"],"nevoie":["fișele pieselor 20 și 21","un șurub M4 cu cap înecat"],"casete":[{"titlu":"SSM","text":["La tăierea filamentului folosiți cleștele, cu tăișul spre masă."]}],"comenzi":[["Rotire exactă","trageți săgeata curbă și tastați unghiul (ex. 45); cu Shift, rotirea sare din 45 în 45°"],["Con","Cone: Base radius, Top radius, Height"],["Vedere în secțiune","cubul de vedere → Right, apoi zoom pe profil"]],"pasi":["Profilul: o cutie 150 × 15,6 × 9 (corpul) + două bare de secțiune pătrată cu latura 3,96, lungi de 150, rotite la 45° în jurul lungimii.","Barele au axa la 7,8 de axa șinei (pe marginile corpului) și la înălțimea Z = 6,2. Lățimea maximă a șinei devine 15,6 + 2 × 2,8 = 21,2.","Grupați: verificați în vederea din dreapta forma de „trapez dublu”.","Canalele: cutie-gaură 5,23 × 25 × 5, care taie 3 mm de sus (de la Z = 6). Primul canal are axa la X = 9,935, deci marginea la 7,32. Ctrl + D de 13 ori, pas 10,01.","Găurile M4 (3×), la X = 15, 75 și 135: cilindru-gaură Ø4,5 de jos până sus + con-gaură (rază 2,25 jos, 4,3 sus) de la Z = 3,7 la 6 + cilindru-gaură Ø8,6 de la Z = 6 până sus (pentru capul șurubului).","Șina 70 (21): 6 canale, primul cu axa la 9,975, găuri la X = 10 și 60.","Imprimați o bucată de probă de 30 mm și încercați pe ea o clemă Picatinny din comerț (dacă aveți) sau corpul C, mai târziu."],"fise":[{"nr":"20","nume":"Șină Picatinny 150","info":"2 buc. pe rover · lecția 8","cote":[{"nr":"1","cota":"Lungime × lățime max. × înălțime","nominal":"150 × 21,2 × 9","tol":"±0,2"},{"nr":"2","cota":"Lățime corp","nominal":"15,6","tol":"±0,15"},{"nr":"3","cota":"Canale (14×): lățime · adâncime","nominal":"5,23 · 3","tol":"±0,1"},{"nr":"4","cota":"Pasul canalelor · primul canal (axă)","nominal":"10,01 · 9,935","tol":"±0,1"},{"nr":"5","cota":"Găuri M4 cap înecat (3×)","nominal":"Ø4,5 · la 15 / 75 / 135","tol":"±0,15"},{"nr":"6","cota":"Con de înecare · degajare","nominal":"Ø4,5→Ø8,6 · Ø8,6","tol":"±0,15"}],"parametri":["PETG, strat 0,2","baza pe masă","4 pereți / 50%","nu (flancuri la 45°)","0,7 h / 17 g"],"img":"img/piese/20.png"},{"nr":"21","nume":"Șină Picatinny 70","info":"1 buc. pe rover · lecția 8","cote":[{"nr":"1","cota":"Lungime × lățime max. × înălțime","nominal":"70 × 21,2 × 9","tol":"±0,2"},{"nr":"2","cota":"Canale (6×): lățime · adâncime","nominal":"5,23 · 3","tol":"±0,1"},{"nr":"3","cota":"Primul canal (axă) · pas","nominal":"9,975 · 10,01","tol":"±0,1"},{"nr":"4","cota":"Găuri M4 cap înecat (2×)","nominal":"Ø4,5 · la 10 / 60","tol":"±0,15"}],"parametri":["PETG, strat 0,2","baza pe masă","4 pereți / 50%","nu (flancuri la 45°)","0,3 h / 8 g"],"img":"img/piese/21.png"}],"control":["Lățimea maximă 21,2","Pasul canalelor 10,01 (verificați distanța primul–ultimul: 13 × 10,01 = 130,13)","Capul șurubului M4 intră sub nivelul canalului"],"reflectie":"De ce se folosesc profiluri standardizate (Picatinny, DIN) în loc de prinderi inventate de noi?","iso":"2027-02-17","quiz":[{"q":"Ce pas au canalele șinei Picatinny?","o":["10 mm","10,01 mm","5,23 mm","15,6 mm"],"a":1,"e":"Pasul standard este 10,01 mm; canalele au 5,23 × 3."},{"q":"Cum se obține lățimea maximă de 21,2?","o":["15,6 + 5,6 = 15,6 + 2 × 2,8","2 × 10,6","15,6 + 3,96","21,2 este lățimea corpului"],"a":0,"e":"Barele rotite la 45° ies câte 2,8 mm de fiecare parte: 15,6 + 2 × 2,8 = 21,2."},{"q":"Cum faci gaura pentru un șurub cu cap înecat?","o":["Doar cilindru-gaură","Cilindru-gaură + con-gaură","Cutie-gaură","Pană-gaură"],"a":1,"e":"Ø4,5 de jos până sus + con-gaură pentru cap + degajare Ø8,6."},{"q":"Șina are 14 canale la pas 10,01. Cât e distanța între primul și ultimul canal?","o":["140,14","130,13","150","10,01"],"a":1,"e":"Între 14 canale sunt 13 pași: 13 × 10,01 = 130,13 mm."}]},{"nr":9,"titlu":"Cârligul pentru șina DIN (EN 60715). Opritorul de capăt","sapt":"S2","data":"jo 18.02.2027","ore":6,"teme":"T4","piese":"17 Opritor pentru șina DIN","scop":"Modelezi profilul care se agață pe șina DIN de 35 mm. Îl salvezi ca bibliotecă și îl refolosești la carcasele A și B. Montezi primele inserții filetate.","stiu":["modelez un profil de prindere pe șină (cârlig cu buză)","copiez un subansamblu între designuri","montez corect o inserție filetată la cald"],"nevoie":["o bucată de șină DIN TS35 × 7,5","inserții M4, letcon cu vârf pentru inserții","fișa piesei 17"],"casete":[{"titlu":"SSM","text":["Letconul se ține doar în suport. Vârful are 240 °C. Mănuși și ochelari obligatorii. Nu răsuciți inserția: apăsați vertical."]}],"comenzi":[["Copiere între designuri","Ctrl + C în designul 1 → deschideți designul 2 → Ctrl + V"],["Plan de lucru pe o față","W + click pe fața piesei; înapoi: W + click pe fundal"]],"pasi":["Măsurați șina DIN: lățime 35, flanșe de 5 mm, grosime 1 mm. Desenați profilul la scara 2:1 în caiet.","Corpul: cutie 8 × 45 × 14, ridicată la Z = 3,5 (dedesubt stau cârligele).","Cârligul (pe fiecare parte): un picior 8 × 2,25 × 3,5 (Z de la 0 la 3,5) + o buză 8 × 3,25 × 2,25 (Z de la 0 la 2,25), lipite una de alta. Între buză și corp rămâne fanta de 1,25 pentru flanșa șinei.","Pozițiile pe Y (de la marginea corpului): picioarele 2,5…4,75 și 40,25…42,5; buzele 4,75…8 și 37…40,25. Deschiderea între buze = 29.","Grupați cârligele și copiați-le într-un design „BIBLIOTECA_DIN”. Le folosiți la carcasele A și B.","Găuri Ø5,6 (din standardele clasei) pentru inserții M4, cu axele la Y = 7,5 și 37,5, centrate pe X.","Imprimați 2 bucăți, culcate pe fața laterală (profilul pe masă). Încercați pe șină: opritorul trebuie să alunece cu frecare ușoară.","Montați inserțiile M4 (demonstrație, apoi fiecare elev câte una)."],"fise":[{"nr":"17","nume":"Opritor pentru șina DIN","info":"8 buc. pe rover · lecția 9","cote":[{"nr":"1","cota":"Lungime × lățime × înălțime","nominal":"8 × 45 × 17,5","tol":"±0,2"},{"nr":"2","cota":"Corp","nominal":"8 × 45 × 14","tol":"±0,2"},{"nr":"3","cota":"Cârlige: deschidere între buze / între picioare","nominal":"29 / 35,5","tol":"±0,15"},{"nr":"4","cota":"Fanta pentru flanșa șinei","nominal":"1,25","tol":"±0,1"},{"nr":"5","cota":"Găuri inserții M4 (2×)","nominal":"Ø5,6 · entraxe 30","tol":"±0,1"}],"parametri":["PETG, strat 0,2","pe o față laterală (profilul pe masă)","4 pereți / 50%","nu","0,2 h / 4 g"],"img":"img/piese/17.png"}],"control":["Alunecă pe șină fără joc vizibil","Inserția este perpendiculară și la 0,2 sub suprafață","Cârligul e salvat în bibliotecă"],"reflectie":"De ce imprimăm opritorul culcat pe o față laterală? Gândiți-vă la straturi și la cârlig.","iso":"2027-02-18","quiz":[{"q":"Ce lățime are șina DIN TS35?","o":["29 mm","35 mm","45 mm","7,5 mm"],"a":1,"e":"TS35 × 7,5: lățime 35, flanșe 5 × 1."},{"q":"Cât este deschiderea între buzele cârligului DIN?","o":["35","29","35,5","1,25"],"a":1,"e":"Deschiderea între buze este 29; fanta pentru flanșă este 1,25."},{"q":"Cum se montează corect o inserție filetată?","o":["Se răsucește cu cleștele","Se apasă vertical cu letconul, fără răsucire, la 0,2 sub suprafață","Se bate cu ciocanul","Se lipește cu adeziv"],"a":1,"e":"Letcon la 230–240 °C, apăsare verticală, fără răsucire, 0,2 sub suprafață."},{"q":"De ce imprimăm opritorul culcat pe o față laterală?","o":["Se imprimă mai repede","Straturile urmăresc profilul cârligului, care devine rezistent și nu cere suport","Ca să încapă mai multe piese pe masă","Pentru că așa cere șina"],"a":1,"e":"Cu profilul pe masă, cârligul nu se rupe între straturi și nu are porțiuni în consolă."}]},{"nr":10,"titlu":"Schița după model: fețele C pentru senzorul ultrasonic și pentru cameră","sapt":"S2","data":"vi 19.02.2027","ore":6,"teme":"T4 · T6","piese":"29 Față C – senzor ultrasunete HC-SR04, 30 Față C – cameră","scop":"Măsori un senzor real, faci schița lui în caiet și modelezi fața care îl ține: HC-SR04 (ultrasunete) și ESP32-CAM (cameră).","stiu":["fac schița după model, cu cote măsurate","adaug jocuri de montaj (+0,3 la găuri, +0,2 la canale)","modelez ghidaje cu canale pentru plăci electronice"],"nevoie":["senzor HC-SR04 și placă ESP32-CAM","șubler","fișele pieselor 29 și 30"],"casete":[{"titlu":"SSM","text":["Senzorii se țin de margini. Nu scoateți camera din conector."]}],"comenzi":[["Spațiul de lucru","W pe fața piesei, ca să așezați forme pe ea"],["Cotare în Tinkercad","R pe un colț; cotele formei selectate apar automat"]],"pasi":["Schițați HC-SR04 în trei vederi: placă 45 × 20, traductoare Ø16, entraxe 26. Măsurați voi și comparați cu valorile din tabel.","Fața 29: fața oarbă + 2 cilindri-gaură Ø16,6 (Ø16 + joc 0,6) cu axele la X = 21,2 și 47,2, Y = 24.","Nervurile care țin placa senzorului: 2 cutii 42 × 1,6 × 6, așezate pe placă (Z de la 2 la 8), de la X = 13,2 la 55,2. Prima la Y = 11,8…13,4, a doua la Y = 34,6…36,2. Distanța dintre ele: 21,2 (placa are 20 + joc).","Fața 30 (camera): fața oarbă + fereastră-gaură 14 × 14 la X = 27,2…41,2, Y = 24…38.","Ghidaje: 2 cutii 3,2 × 36 × 14 (Z de la 2 la 16), la X = 17,6…20,8 și 47,6…50,8, Y = 4…40.","Canalele pentru placa camerei: câte o cutie-gaură 1,2 × 40 × 1,8, tăiată în fața interioară a fiecărui ghidaj, la 9,1…10,9 deasupra plăcii.","Imprimați și probați senzorii reali. Notați jocurile pe fișă."],"fise":[{"nr":"29","nume":"Față C – senzor ultrasunete HC-SR04","info":"1 buc. pe rover · lecția 10","cote":[{"nr":"1","cota":"Placă","nominal":"68,4 × 43,7 × 2","tol":"±0,1"},{"nr":"2","cota":"Găuri traductoare (2×)","nominal":"Ø16,6 · entraxe 26","tol":"±0,15"},{"nr":"3","cota":"Axa găurilor de la marginea de jos","nominal":"24","tol":"±0,2"},{"nr":"4","cota":"Nervuri de prindere (2×)","nominal":"42 × 6 × 1,6 · distanța 21,2","tol":"±0,15"}],"parametri":["PETG, strat 0,2","fața din față pe masă, nervurile în sus","3 pereți / 20%","nu","0,3 h / 6 g"],"img":"img/piese/29.png"},{"nr":"30","nume":"Față C – cameră ESP32-CAM","info":"1 buc. pe rover · lecția 10","cote":[{"nr":"1","cota":"Placă","nominal":"68,4 × 43,7 × 2","tol":"±0,1"},{"nr":"2","cota":"Fereastra camerei","nominal":"14 × 14","tol":"±0,15"},{"nr":"3","cota":"Ghidaje (2×)","nominal":"3,2 × 14 × 36","tol":"±0,2"},{"nr":"4","cota":"Distanța interioară între ghidaje","nominal":"26,8","tol":"±0,15"},{"nr":"5","cota":"Canale pentru placă (2×)","nominal":"1,2 × 1,8 · la 9,1 de placă","tol":"±0,1"}],"parametri":["PETG, strat 0,2","fața din față pe masă, ghidajele în sus","3 pereți / 20%","nu","0,4 h / 9 g"],"img":"img/piese/30.png"}],"control":["Schița are cotele măsurate de voi","Traductoarele intră fără forțare","Camera alunecă în canale și nu cade"],"reflectie":"Ce joc ați lăsat la găurile traductoarelor? De ce nu modelăm gaura exact Ø16?","iso":"2027-02-19","quiz":[{"q":"Traductoarele HC-SR04 au Ø16. Ce gaură modelăm?","o":["Ø16","Ø16,6","Ø15,4","Ø18"],"a":1,"e":"Pentru un corp rotund cumpărat lăsăm +0,3 … +0,6 la diametru: Ø16 → Ø16,6."},{"q":"Ce este o schiță după model?","o":["Un desen copiat din internet","Un desen făcut după piesa reală, cu cote măsurate","Un model 3D","O fotografie a piesei"],"a":1,"e":"Măsurăm senzorul real cu șublerul și desenăm vederile cu cotele noastre."},{"q":"Placa senzorului are 20 mm. De ce nervurile sunt la 21,2 una de alta?","o":["Greșeală de proiectare","Lăsăm joc de montaj, ca placa să intre fără forțare","Pentru aerisire","Ca să încapă două plăci"],"a":1,"e":"Jocul de montaj permite introducerea plăcii fără forțare."}]},{"nr":11,"titlu":"Carcasa B: corp gol, stâlpi, bosaje, aerisire","sapt":"S3","data":"lu 15.03.2027","ore":6,"teme":"T4","piese":"12 Carcasa B (DIN)","scop":"Modelezi prima carcasă cu pereți: un corp gol cu fund. Adaugi stâlpi pentru capac, bosaje pentru placa de montaj, cârligele DIN din bibliotecă și găuri „knock-out” care se deschid doar când e nevoie.","stiu":["obțin un corp gol din două cutii rotunjite (exterior − interior)","adaug stâlpi și bosaje cu găuri pentru inserții","fac o gaură orizontală în formă de picătură (fără suport la imprimare)","reutilizez cârligele DIN din bibliotecă"],"nevoie":["biblioteca DIN","capacul B (13) și placa B (16), pentru verificarea găurilor","fișa piesei 12"],"casete":[{"titlu":"SSM","text":["Mențineți ordinea la masa de lucru: piesele imprimate stau în cutia echipei, etichetate."]}],"comenzi":[["Corp gol","cutie exterioară (plin) + cutie interioară (gaură), ridicată cu grosimea fundului"],["Gaură „picătură”","cilindru orizontal + pătrat cu latura = raza, rotit la 45°, cu colțul de jos în centrul găurii; grupați și faceți gaură"],["Aliniere pe 3 axe","L, apoi punctele de pe X, Y și Z"]],"pasi":["Corpul: cutie 43 × 120 × 33,5, Radius 3, ridicată la Z = 3,5. Gaura interioară: cutie 38,2 × 115,2, Radius 1,5, de la Z = 6,5 (fund de 3 mm) până sus.","Stâlpii capacului (4×): cutii 7 × 7, pe toată înălțimea, în colțurile interioare. Axele: X = 5,9 și 37,1, Y = 5,9 și 114,1 (ca găurile capacului). Găuri Ø4 (inserții M3), adânci de 7 mm de sus.","Bosajele plăcii (4×): cilindri Ø8 de la fund (Z 3,5…10,5), cu axele la X = 12 și 31, Y = 14 și 106. Găuri Ø4 adânci de 6 mm, de sus.","Cârligele DIN: lipiți din bibliotecă profilul, pe toată lungimea de 43 (de-a lungul lui X), centrat pe Y = 60.","Knock-out (2×): pe pereții de capăt (Y = 0 și Y = 120), o picătură Ø12,5 cu axa la X = 21,5, Z = 19,5, adâncă de 2,0 din exterior. Rămâne o membrană de 0,4, care se sparge cu șurubelnița doar dacă e nevoie de cablu.","Aerisirea: pe pereții lungi (X = 0 și X = 43), 9 fante 3 × 16, la Z = 12,5…28,5, cu axele la Y = 20, 30, … 100 (pas 10).","Grupați. Verificați cu capacul 13 și placa 16 (puneți-le în design): găurile trebuie să cadă exact peste stâlpi și bosaje."],"fise":[{"nr":"12","nume":"Carcasa B (DIN)","info":"2 buc. pe rover · lecția 11","cote":[{"nr":"1","cota":"Lungime × lățime × înălțime (cu cârlige)","nominal":"43 × 120 × 37 · R3","tol":"±0,3"},{"nr":"2","cota":"Perete / fund","nominal":"2,4 / 3","tol":"±0,2"},{"nr":"3","cota":"Stâlpi capac (4×) · găuri inserții M3","nominal":"7 × 7 · Ø4 × 7","tol":"±0,1"},{"nr":"4","cota":"Bosaje placă (4×)","nominal":"Ø8 × 4 · entraxe 19 × 92","tol":"±0,2"},{"nr":"5","cota":"Cârlige DIN: deschidere între buze","nominal":"29","tol":"±0,15"},{"nr":"6","cota":"Găuri „knock-out” (2×)","nominal":"Ø12,5 · membrană 0,4","tol":"±0,2"},{"nr":"7","cota":"Fante de aerisire (2 × 9)","nominal":"3 × 16 · pas 10","tol":"±0,2"}],"parametri":["PETG, strat 0,2","ca la carcasa A","3 pereți / 20%","doar sub cârlige","2,0 h / 47 g"],"img":"img/piese/12.png"}],"control":["Pereți 2,4, fund 3","Găurile capacului cad pe stâlpi","Găurile plăcii cad pe bosaje","Picătura are vârful în sus"],"reflectie":"De ce gaura orizontală are formă de picătură cu vârful în sus? Ce s-ar întâmpla la imprimare cu o gaură rotundă de Ø27?","iso":"2027-03-15","quiz":[{"q":"Cum obții un corp gol în Tinkercad?","o":["Cu Tube","Cutie plină − cutie-gaură ridicată cu grosimea fundului","Scalând o cutie","Cu Wedge"],"a":1,"e":"Cutia interioară (gaură) pornește de la Z = grosimea fundului."},{"q":"Ce formă are o gaură orizontală care se imprimă fără suport?","o":["Rotundă","Picătură cu vârful în sus","Picătură cu vârful în jos","Pătrată"],"a":1,"e":"Vârful de 45° în sus se imprimă fără să se prăbușească plafonul găurii."},{"q":"Ce este o gaură „knock-out”?","o":["O gaură uitată","O gaură închisă cu o membrană de 0,4, spartă doar dacă e nevoie de cablu","O gaură de aerisire","O gaură pentru inserție"],"a":1,"e":"Membrana de 0,4 mm se sparge cu șurubelnița doar unde trece un cablu."},{"q":"Ce grosime au peretele și fundul carcasei B?","o":["2 / 2","2,4 / 3","3 / 6","1,6 / 2,4"],"a":1,"e":"Perete 2,4 mm (6 perimetre × 0,4), fund 3 mm."}]},{"nr":12,"titlu":"Carcasa A: scalare inteligentă și grila ventilatorului","sapt":"S3","data":"ma 16.03.2027","ore":6,"teme":"T4","piese":"10 Carcasa A (DIN)","scop":"Pornești de la carcasa B și obții carcasa A (dublă). Adaugi grila pentru un ventilator de 30 mm, care răcește driverele motoarelor.","stiu":["modific un model existent fără să-l deformez (nu scalez găurile)","poziționez elemente simetric","fac grilă de ventilator cu găuri de prindere"],"nevoie":["designul carcasei B","un ventilator de 30 mm","fișa piesei 10"],"casete":[{"titlu":"SSM","text":["Ventilatorul se probează doar nealimentat."]}],"comenzi":[["Degrupare","Ctrl + Shift + G: modificați doar formele care trebuie"],["Oglindire","M + săgeata axei"]],"pasi":["Copiați carcasa B. Degrupați. Nu scalați grupul: s-ar mări și găurile, și pereții. Modificați separat: cutia exterioară la 86, cea interioară la 81,2.","Mutați stâlpii și bosajele pe pozițiile noi: stâlpi la X = 5,9 și 80,1; bosaje la X = 12 și 74.","Knock-out: câte 2 pe fiecare perete de capăt, cu axele la X = 18 și 68.","Cârligele DIN: prelungiți-le la 86.","Grila ventilatorului, pe peretele X = 0: picătură Ø27 cu axa la Y = 90, Z = 21,7 + 4 găuri Ø3,2 la ±12 mm de axa grilei (entraxe 24).","Grupați și comparați cu fișa piesei. Puneți în design capacul 11 și placa 14 sau 15, pentru verificare."],"fise":[{"nr":"10","nume":"Carcasa A (DIN)","info":"3 buc. pe rover · lecția 12","cote":[{"nr":"1","cota":"Lungime × lățime × înălțime (cu cârlige)","nominal":"86 × 120 × 37 · R3","tol":"±0,3"},{"nr":"2","cota":"Perete / fund","nominal":"2,4 / 3","tol":"±0,2"},{"nr":"3","cota":"Stâlpi capac (4×) · găuri inserții M3","nominal":"7 × 7 · Ø4 × 7","tol":"±0,1"},{"nr":"4","cota":"Bosaje placă (4×)","nominal":"Ø8 × 4 · entraxe 62 × 92","tol":"±0,2"},{"nr":"5","cota":"Cârlige DIN: deschidere între buze / între picioare","nominal":"29 / 35,5","tol":"±0,15"},{"nr":"6","cota":"Găuri „knock-out” (4×)","nominal":"Ø12,5 · membrană 0,4","tol":"±0,2"},{"nr":"7","cota":"Grila ventilatorului · găuri","nominal":"Ø27 · 4 × Ø3,2 entraxe 24","tol":"±0,2"},{"nr":"8","cota":"Fante de aerisire (2 × 9)","nominal":"3 × 16 · pas 10","tol":"±0,2"}],"parametri":["PETG, strat 0,2","fundul pe masă; cârligele 3 pe suport, sau întoarsă","pereți / 20%","doar sub cârlige","3,1 h / 70 g"],"img":"img/piese/10.png"}],"control":["Găurile au rămas cu diametrele standard","Grila are entraxele 24 × 24","Capacul A se potrivește"],"reflectie":"Ce s-ar fi întâmplat dacă ați fi scalat carcasa B de 2 ori pe lungime? Dați două exemple de cote greșite.","iso":"2027-03-16","quiz":[{"q":"De ce nu scalăm carcasa B de 2 ori ca să obținem carcasa A?","o":["Pentru că Tinkercad nu poate","S-ar mări și găurile, și pereții","Pentru că ar ieși prea ușoară","Pentru că A e mai înaltă"],"a":1,"e":"Degrupăm și modificăm doar cutiile; găurile rămân la diametrele standard."},{"q":"Ce entraxe au găurile ventilatorului de 30 mm?","o":["30","24","27","12"],"a":1,"e":"4 găuri Ø3,2 la ±12 mm de axa grilei: entraxe 24."},{"q":"Ce tastă oglindește o formă?","o":["L","M","W","D"],"a":1,"e":"M + săgeata axei = oglindire."}]},{"nr":13,"titlu":"Carcasa C: corp și falcă mobilă pe șina Picatinny","sapt":"S3","data":"mi 17.03.2027","ore":6,"teme":"T4","piese":"22 Carcasa C – corp, 23 Carcasa C – falcă mobilă","scop":"Modelezi carcasa modulelor C (accesorii). Se prinde pe șina Picatinny cu o falcă fixă și o falcă mobilă, strânse cu 2 șuruburi M3. Fața din față glisează în canale.","stiu":["modelez o prindere prin strângere (clemă) pe un profil standard","fac locaș hexagonal pentru piuliță (prizonieră)","fac canale de glisare pentru fețe interschimbabile"],"nevoie":["șina Picatinny imprimată (20 sau 21)","șuruburi M3 × 40, piulițe M3","fișele pieselor 22 și 23"],"casete":[{"titlu":"SSM","text":["Piulițele prizoniere se presează cu un șurub, nu cu ciocanul."]}],"comenzi":[["Poligon","Polygon: Sides = 6, Radius = 3,35 (cheie S5,8)"],["Pană (Wedge)","pentru teșituri la 45°"]],"pasi":["Corpul: cutie 70 × 50 × 50, ridicată la Z = 8,5. Golul: cutie-gaură 65,2 × 48,6, de la X = 2,4, Y = 2,4 și Z = 14,5 (baza de 6). Iese prin față: corpul rămâne deschis în sus și în față.","Canalele feței: în pereții laterali, de la interior, cutii-gaură 1,81 × 2,2, cu Y de la 44,9 la 47,1, pe toată înălțimea golului.","Stâlpii capacului: 2 cutii 6 × 6 în colțurile din spate, cu găuri Ø4 adânci de 7 mm, cu axele la (5,4; 5,4) și (64,6; 5,4).","Falca fixă (sub bază, pe partea din spate): profil 6 × 8,5 (Y de la 11 la 17), pe toată lungimea de 70. În fața ei, o crestătură în V: pătrat-gaură cu latura 3,96, rotit la 45°, cu centrul la Y = 17 și Z = 5,7 (înălțimea muchiei șinei).","Șuruburile de strângere: găuri-picătură Ø3,4 pe direcția Y, pe toată lățimea, cu axele la X = 20 și 50, Z = 6,9.","Ieșirea cablului: picătură Ø10 în peretele din spate, cu axa la X = 35, Z = 22,5.","Falca mobilă (23): oglinda falcii fixe (M), lungă de 70, lată de 6, înaltă de 8,2. Pe fața exterioară, locașuri hexagonale S5,8, adânci de 3, în axa găurilor.","Imprimați corpul cu fălcile în sus și falca mobilă culcată. Probați pe șină."],"fise":[{"nr":"22","nume":"Carcasa C – corp","info":"5 buc. pe rover · lecția 13","cote":[{"nr":"1","cota":"Lungime × lățime × înălțime (cu falca)","nominal":"70 × 50 × 58,5","tol":"±0,3"},{"nr":"2","cota":"Perete / bază","nominal":"2,4 / 6","tol":"±0,2"},{"nr":"3","cota":"Canale pentru fața glisantă (2×)","nominal":"1,8 × 2,2","tol":"±0,1"},{"nr":"4","cota":"Stâlpi capac (2×) · găuri inserții M3","nominal":"6 × 6 · Ø4 × 7","tol":"±0,1"},{"nr":"5","cota":"Găuri șuruburi de strângere (2×)","nominal":"Ø3,4 · entraxe 30","tol":"±0,15"},{"nr":"6","cota":"Ieșire cablu (spate)","nominal":"Ø10","tol":"±0,2"},{"nr":"7","cota":"Falca fixă: crestătura în V (adâncime)","nominal":"2,8 la z = −2,8","tol":"±0,15"}],"parametri":["PETG, strat 0,2","fălcile în sus (gura carcasei pe masă)","3 pereți / 20%","nu","2,1 h / 47 g"],"img":"img/piese/22.png"},{"nr":"23","nume":"Carcasa C – falcă mobilă","info":"5 buc. pe rover · lecția 13","cote":[{"nr":"1","cota":"Lungime × lățime × înălțime","nominal":"70 × 6 × 8,2","tol":"±0,2"},{"nr":"2","cota":"Găuri șuruburi (2×)","nominal":"Ø3,4 · entraxe 30","tol":"±0,15"},{"nr":"3","cota":"Locaș piuliță M3 (hexagon)","nominal":"S5,8 × 3","tol":"±0,1"}],"parametri":["PETG, strat 0,2","culcată, profilul pe masă","umplere 100%","nu","0,1 h / 3 g"],"img":"img/piese/23.png"}],"control":["Corpul se strânge pe șină fără să joace","Piulița intră în locaș și nu se rotește","Canalele primesc fața oarbă (33)"],"reflectie":"De ce are clema o falcă fixă și una mobilă? Ce avantaj are față de o clemă dintr-o singură bucată?","iso":"2027-03-17","quiz":[{"q":"Cu ce formă faci locașul piuliței M3?","o":["Cilindru cu 6 laturi sau Polygon cu Sides = 6","Cutie","Con","Tub"],"a":0,"e":"Polygon: Sides = 6, Radius = 3,35 (cheie S5,8)."},{"q":"Ce rol are piulița prizonieră?","o":["Decorează piesa","Stă blocată în locaș și nu se rotește la strângere","Ține capacul","Reglează înălțimea"],"a":1,"e":"Hexagonul nu lasă piulița să se rotească, așa că strângem doar șurubul."},{"q":"Cum se prinde carcasa C pe șina Picatinny?","o":["Cu adeziv","Cu o falcă fixă și una mobilă, strânse cu 2 șuruburi M3","Cu bandă dublu adezivă","Cu cârlige DIN"],"a":1,"e":"Clema din două fălci se strânge pe profilul șinei cu 2 șuruburi M3 × 40."}]},{"nr":14,"titlu":"Capacele speciale C și domul girofarului","sapt":"S3","data":"jo 18.03.2027","ore":6,"teme":"T4","piese":"25 Capac C pentru lidar LD19, 26 Capac C pentru girofar, 27 Capac C pentru butonul STOP, 28 Dom girofar","scop":"Modelezi capacele care transformă un modul C în lidar, girofar sau buton de oprire de urgență. Modelezi domul translucid al girofarului: o piesă de revoluție cu pereți subțiri.","stiu":["construiesc o piesă de revoluție din cilindri și conuri","golesc o piesă păstrând grosimea peretelui constantă","respect un standard de siguranță (ISO 13850: butonul de urgență este roșu, pe fond galben, Ø22)"],"nevoie":["capacul simplu (24)","buton de urgență Ø22, inel LED WS2812 cu 8 LED-uri","fișele pieselor 25–28"],"casete":[{"titlu":"SSM","text":["Butonul de oprire de urgență se montează doar cu contactul normal închis (NC) în circuit."]}],"comenzi":[["Tub","Tube: Radius, Wall Thickness, Sides"],["Con trunchiat","Cone: Top radius > 0"]],"pasi":["Capacul lidar (25): capacul simplu + cadru: cutie 47 × 47 × 6 minus cutie-gaură 39,4 × 39,4, centrat la (35; 27), așezat pe capac. Gaura cablului Ø12 în centru.","Găurile chingii: găuri Ø3,4 pe direcția X, prin tot cadrul, cu axele la Y = 7 și 47, Z = 5,5.","Capacul girofarului (26): capacul simplu + tub Ø40, perete 3,6 (Ø interior 32,8), înalt de 3, centrat la (35; 27). Inelul de LED-uri stă în interior. Gaura cablului: Ø8.","Capacul STOP (27): placă 70 × 50 × 4, gaură Ø22,5 centrată la (35; 27). Canalul anti-rotire: cutie-gaură 3,2 × 1,7 la marginea de sus a găurii (X = 33,4…36,6, Y = 38…39,7).","Domul (28): cilindru Ø46 × 3 + cilindru Ø44 × 14 (Z 3…17) + con Ø44 → Ø18, înalt de 12 (Z 17…29).","Golul domului: cilindru-gaură Ø40,6 de jos până la Z = 3, cilindru-gaură Ø40,8 de la Z = 2,9 la 17, con-gaură Ø40,8 → Ø19,8 de la Z = 17 la 27,4. Peretele rămâne de ≈ 1,6.","Imprimați domul din PETG roșu translucid, cu 2 pereți și 0% umplere."],"fise":[{"nr":"25","nume":"Capac C pentru lidar LD19","info":"1 buc. pe rover · lecția 14","cote":[{"nr":"1","cota":"Placă","nominal":"70 × 50 × 2,5","tol":"±0,2"},{"nr":"2","cota":"Cadru: exterior / interior / înălțime","nominal":"47 / 39,4 / 6","tol":"±0,15"},{"nr":"3","cota":"Gaură cablu","nominal":"Ø12","tol":"±0,2"},{"nr":"4","cota":"Găuri pentru chingă (2×)","nominal":"Ø3,4 · entraxe 40","tol":"±0,15"}],"parametri":["PETG, strat 0,2","plat, cadrul în sus","3 pereți / 20%","nu","0,6 h / 13 g"],"img":"img/piese/25.png"},{"nr":"26","nume":"Capac C pentru girofar","info":"1 buc. pe rover · lecția 14","cote":[{"nr":"1","cota":"Placă","nominal":"70 × 50 × 2,5","tol":"±0,2"},{"nr":"2","cota":"Inel de așezare (Øext / Øint / h)","nominal":"40 / 32,8 / 3","tol":"±0,15"},{"nr":"3","cota":"Gaură cablu","nominal":"Ø8","tol":"±0,2"}],"parametri":["PETG, strat 0,2","plat, inelul în sus","3 pereți / 20%","nu","0,5 h / 11 g"],"img":"img/piese/26.png"},{"nr":"27","nume":"Capac C pentru butonul STOP","info":"1 buc. pe rover · lecția 14","cote":[{"nr":"1","cota":"Placă","nominal":"70 × 50 × 4","tol":"±0,2"},{"nr":"2","cota":"Gaura butonului (ISO 13850, Ø22)","nominal":"Ø22,5","tol":"±0,1"},{"nr":"3","cota":"Canal anti-rotire","nominal":"3,2 × 1,7","tol":"±0,1"}],"parametri":["PETG, strat 0,2","plat","3 pereți / 20%","nu","0,6 h / 13 g"],"img":"img/piese/27.png"},{"nr":"28","nume":"Dom girofar (PETG roșu translucid)","info":"1 buc. pe rover · lecția 14","cote":[{"nr":"1","cota":"Diametru bază · înălțime totală","nominal":"Ø46 · 29","tol":"±0,2"},{"nr":"2","cota":"Cilindru · con (Ø sus)","nominal":"Ø44 × 14 · Ø18","tol":"±0,2"},{"nr":"3","cota":"Ø interior la bază (peste inelul de 40)","nominal":"Ø40,6","tol":"±0,15"},{"nr":"4","cota":"Grosime perete","nominal":"1,6","tol":"±0,1"}],"parametri":["PETG roșu translucid","baza pe masă","2 pereți / 0%","nu","0,3 h / 6 g"],"img":"img/piese/28.png"}],"control":["Butonul de 22 mm intră și nu se rotește","Domul intră peste inelul de 40 cu frecare ușoară","Peretele domului ≈ 1,6 peste tot"],"reflectie":"De ce are domul vârful conic, nu plat? (Gândiți-vă la imprimare: ce ar însemna un tavan plat de Ø40?)","iso":"2027-03-18","quiz":[{"q":"Cum arată butonul de oprire de urgență după ISO 13850?","o":["Verde pe fond alb","Roșu pe fond galben","Negru pe fond roșu","Albastru"],"a":1,"e":"Buton roșu pe fond galben, montat într-o gaură Ø22 (la noi Ø22,5) cu canal anti-rotire."},{"q":"Cum imprimăm domul girofarului?","o":["4 pereți, 100%","2 pereți, 0% umplere, PETG roșu translucid","3 pereți, 20%, PLA alb","Cu suporturi"],"a":1,"e":"Peretele de ≈ 1,6 mm (2 perimetre) lasă lumina LED-urilor să treacă."},{"q":"La ce folosește canalul de 3,2 × 1,7 de lângă gaura butonului?","o":["Aerisire","Împiedică rotirea butonului","Trecerea cablului","Scurgerea apei"],"a":1,"e":"Canalul anti-rotire primește pintenul butonului."}]},{"nr":15,"titlu":"Asamblarea digitală și fizică a unui modul C complet","sapt":"S3","data":"vi 19.03.2027","ore":6,"teme":"T5","piese":"—","scop":"Pui într-un singur design toate piesele unui modul C: șină, corp, falcă, față, capac. Verifici interferențele, apoi asamblezi fizic modulul.","stiu":["import piese STL într-un design de asamblare","verific suprapunerile în secțiune","asamblez fizic un modul și completez fișa de control"],"nevoie":["toate piesele C imprimate","șuruburi M3 × 40, piulițe, inserții M3","șurubelniță, cheie hexagonală 2,5"],"casete":[{"titlu":"SSM","text":["La montajul inserțiilor: letconul doar în suport, mănuși și ochelari."]}],"comenzi":[["Import","Import → fișier STL (scara 100%)"],["Secțiune","o cutie-gaură mare, ca să „tăiați” asamblarea și să vedeți interiorul (nu grupați!)"]],"pasi":["Design nou FMR2_ASM_C_Nume. Importați: șina 21, corpul 22, falca 23, fața 29 (sau alta), capacul 26.","Așezați piesele în poziția de montaj: corpul pe șină, falca opusă falcii fixe, fața în canale, capacul pe stâlpi.","Cutie-gaură de „secțiune”: o puneți peste jumătate din asamblare și o selectați împreună cu piesele (nu grupați). Așa vedeți dacă piesele intră una în alta (interferență).","Notați pe fișa de control jocurile observate.","Asamblarea fizică: inserțiile M3 în stâlpi, falca cu piulițele, prinderea pe șină, fața, capacul.","Fotografiați modulul pentru portofoliu."],"fise":[],"control":["Nicio interferență în asamblarea digitală","Modulul se strânge pe șină cu mâna","Fața glisează, capacul se închide"],"reflectie":"Ce ați corectat în modele după asamblarea fizică?","iso":"2027-03-19","quiz":[{"q":"Cum vezi dacă piesele dintr-o asamblare intră una în alta?","o":["Grupezi totul","Pui o cutie-gaură de secțiune peste asamblare, fără să grupezi","Exporți STL","Schimbi culoarea"],"a":1,"e":"Cutia-gaură selectată împreună cu piesele „taie” vizual asamblarea, fără să o modifice."},{"q":"La ce scară importăm fișierele STL?","o":["50%","100%","200%","10%"],"a":1,"e":"Import → fișier STL, scara 100%, ca să păstrăm cotele reale."},{"q":"Ce înseamnă interferență?","o":["Joc prea mare","Două piese ocupă același spațiu","Culori diferite","O piesă lipsă"],"a":1,"e":"La interferență piesele intră una în alta și nu se pot monta."}]},{"nr":16,"titlu":"Butucul de antrenare: alezaj în D, piesă de rezistență","sapt":"S4","data":"lu 10.05.2027","ore":6,"teme":"T4","piese":"03 Butuc de antrenare (arbore 5 mm cu plat)","scop":"Modelezi butucul care transmite cuplul de la motor la roată: alezaj în D pe arborele de 5 mm, gaură radială pentru știft și 4 găuri pentru inserții. Imprimi cu umplere 100%.","stiu":["modelez un alezaj cu formă (D) pe un arbore standard","aleg parametrii de imprimare după solicitarea piesei","controlez ajustajul pe arbore"],"nevoie":["un motor NEMA 17 (arbore Ø5 cu plat)","inserții M3","fișa piesei 03"],"casete":[{"titlu":"SSM","text":["Motorul se probează doar nealimentat. Nu băgați degetele între roată și suport."]}],"comenzi":[["Simetrie polară simplă","4 găuri la 45°: puneți gaura pe diagonala pătratului, apoi oglindiți (M) pe X și pe Y"]],"pasi":["Flanșa: cilindru Ø30 × 5 (laturi 64). Butucul: cilindru Ø16 × 9, așezat pe flanșă (Z de la 5 la 14).","Alezajul în D: cilindru Ø5,2 + cutie care taie planul la 2,1 de axă (pe +X). Grupați, faceți gaură, centrați pe toată înălțimea.","Găurile inserțiilor (4×): Ø4,0 (sau valoarea clasei) pe cercul de Ø22, la 45°: axele la (±7,78; ±7,78) față de centru, prin flanșă.","Gaura radială: cilindru Ø4,0 orizontal, din axă spre +X (spre plat), la Z = 9,5. Inserția din ea primește un știft M3 × 6 care apasă pe planul arborelui.","Imprimați cu flanșa pe masă, 100% umplere. Probați pe arbore: trebuie să intre cu o apăsare ușoară, fără joc la rotire."],"fise":[{"nr":"03","nume":"Butuc de antrenare (arbore 5 mm cu plat)","info":"4 buc. pe rover · lecția","cote":[{"nr":"1","cota":"Flanșă (Ø × grosime)","nominal":"Ø30 × 5","tol":"±0,2"},{"nr":"2","cota":"Butuc (Ø × lungime)","nominal":"Ø16 × 9","tol":"±0,2"},{"nr":"3","cota":"Înălțime totală","nominal":"14","tol":"±0,2"},{"nr":"4","cota":"Alezaj în D (Ø / distanța de la ax la plat)","nominal":"Ø5,2 / 2,1","tol":"+0,1 / 0"},{"nr":"5","cota":"Găuri inserții M3 (4×)","nominal":"Ø4,0 pe Ø22","tol":"±0,1"},{"nr":"6","cota":"Gaură radială inserție M3 (spre plat)","nominal":"Ø4,0 la z = 9,5","tol":"±0,1"}],"parametri":["PETG, strat 0,2","flanșa pe masă","umplere 100%","nu","0,3 h / 6 g"],"img":"img/piese/03.png"}],"control":["Butucul intră pe arbore fără joc unghiular","Găurile sunt pe Ø22","Gaura radială e în dreptul planului"],"reflectie":"De ce imprimăm butucul cu umplere 100%, iar capacele cu doar 20%?","iso":"2027-05-10","quiz":[{"q":"Ce cote are alezajul în D al butucului?","o":["Ø5, plat la 2,5","Ø5,2, plat la 2,1 de axă","Ø4, plat la 2","Ø6, fără plat"],"a":1,"e":"Ø5,2 cu planul la 2,1 de axă, după șablonul E1."},{"q":"De ce imprimăm butucul cu umplere 100%?","o":["Arată mai bine","Transmite cuplul motorului: este o piesă de rezistență","Se imprimă mai repede","Consumă mai puțin material"],"a":1,"e":"Piesele solicitate primesc umplere mare; capacele, doar 20%."},{"q":"4 găuri pe cercul de Ø22, la 45°. Ce coordonate au față de centru?","o":["(±11; ±11)","(±7,78; ±7,78)","(±5,5; ±5,5)","(±22; ±22)"],"a":1,"e":"R = 11; 11 × cos 45° ≈ 7,78."}]},{"nr":17,"titlu":"Roata fără aer (I): banda, inelul interior, discul și coloana","sapt":"S4","data":"ma 11.05.2027","ore":6,"teme":"T4","piese":"02 Roată fără aer Ø160 × 70","scop":"Modelezi partea rigidă a roții fără aer (tip airless): banda de rulare, inelul interior, discul cu ferestre și coloana de prindere. Spițele elastice vin în lecția următoare.","stiu":["folosesc tubul (Tube) pentru inele","repet forme în jurul unei axe (simetrie polară)","înțeleg rolul fiecărei zone: rigidă / elastică"],"nevoie":["fișa piesei 02, desenul secțiunii roții","calculul din dosarul tehnic (7 kg pe roată)"],"casete":[{"titlu":"SSM","text":["Roțile imprimate se manipulează cu grijă: spițele de 1,6 mm se pot rupe la lovire."]},{"titlu":"CUM FUNCȚIONEAZĂ ROATA FĂRĂ AER","text":["Coloana, discul și inelul interior sunt rigide: transmit cuplul de la butuc. Spițele subțiri în arc sunt elastice: se îndoaie puțin și amortizează denivelările. Banda de rulare împarte greutatea pe mai multe spițe. Calculul cu elemente finite din dosarul tehnic arată că roata ține 7 kg, cu un coeficient de siguranță de peste 2."]}],"comenzi":[["Tub cu multe laturi","Tube: Sides = 64 (maximul formei)"],["Inel-ajutor pentru rotire","Tinkercad rotește în jurul centrului selecției. Un tub-gaură mare (202 × 202), centrat pe axa roții și selectat împreună cu forma, mută centrul rotirii pe axă."]],"pasi":["Așezați centrul roții în originea riglei (rigla comutată pe „centru”). Toată roata se construiește în jurul acestei axe.","Banda: tub cu rază 80, perete 4, înălțime 70.","Inelul interior: tub cu rază 56,5, perete 3, înălțime 70.","Discul: cilindru Ø108 × 6 (Z 0…6). Ferestrele: cilindru-gaură Ø24 cu axa la 37 de centru, la 30°. Selectați-l împreună cu inelul-ajutor, Ctrl + D, rotiți 60°, apoi încă 4 × Ctrl + D: 6 ferestre.","Nervurile: 3 cutii 108 × 3 × 24, centrate pe axă, rotite la 0°, 60° și 120° (centrul lor e deja pe axă, deci nu trebuie inel-ajutor).","Coloana: cilindru Ø32 × 27. Gaură centrală Ø12. 4 găuri Ø3,4 pe Ø22 (la 45°), cu lamaj Ø6,5 adânc de 3,5 pe fața exterioară (Z 0…3,5).","Grupați partea rigidă și salvați versiunea „v1_rigid”."],"fise":[{"nr":"02","nume":"Roată fără aer Ø160 × 70","info":"4 buc. pe rover · lecția 17","cote":[{"nr":"1","cota":"Diametru exterior × lățime","nominal":"Ø160 × 70","tol":"±0,5"},{"nr":"2","cota":"Banda de rulare (grosime)","nominal":"4","tol":"±0,2"},{"nr":"3","cota":"Inel interior (rază ext. / grosime)","nominal":"R56,5 / 3","tol":"±0,2"},{"nr":"4","cota":"Spițe (14×): grosime · unghi","nominal":"1,6 · 90°","tol":"±0,1"},{"nr":"5","cota":"Canale anti-alunecare (36×)","nominal":"3 × 1,5 · z 4…66","tol":"±0,3"},{"nr":"6","cota":"Disc (grosime) · 6 ferestre","nominal":"6 · Ø24 pe R37","tol":"±0,2"},{"nr":"7","cota":"Coloană (Ø × înălțime)","nominal":"Ø32 × 27","tol":"±0,2"},{"nr":"8","cota":"Găuri prindere (4×) · lamaj","nominal":"Ø3,4 pe Ø22 · Ø6,5 × 3,5","tol":"±0,15"}],"parametri":["PETG, strat 0,2","fața exterioară (discul) pe masă","4 pereți / 30% giroid · spițe la ≈ 40 mm/s","nu","21,8 h / 499 g"],"img":"img/piese/02.png"}],"control":["Toate formele sunt concentrice","6 ferestre între nervuri","Coloana și găurile se potrivesc cu butucul 03"],"reflectie":"De ce are discul ferestre și nervuri, în loc să fie plin?","iso":"2027-05-11","quiz":[{"q":"Discul are 6 ferestre. La ce unghi le repetăm?","o":["45°","60°","30°","90°"],"a":1,"e":"360° / 6 = 60°."},{"q":"Care zonă a roții fără aer este elastică?","o":["Coloana","Spițele","Discul","Inelul interior"],"a":1,"e":"Coloana, discul și inelul sunt rigide; spițele subțiri în arc amortizează."},{"q":"La ce folosește inelul-ajutor (tub-gaură 202 × 202)?","o":["Face roata mai ușoară","Mută centrul rotirii pe axa roții","Taie banda","Este banda de rulare"],"a":1,"e":"Tinkercad rotește în jurul centrului selecției; inelul-ajutor aduce acest centru pe axă."}]},{"nr":18,"titlu":"Roata fără aer (II): spițele în arc și canalele benzii","sapt":"S4","data":"mi 12.05.2027","ore":6,"teme":"T4 · T3","piese":"02 Roată fără aer Ø160 × 70","scop":"Construiești cele 14 spițe elastice în arc de cerc. Ele dau amortizarea, dar țin 7 kg pe roată. Adaugi canalele anti-alunecare și pregătești imprimarea celor 4 roți (≈ 22 h fiecare).","stiu":["construiesc un arc de cerc dintr-un tub tăiat cu găuri","fac o repetare polară cu pas neîntreg (360° / 14 = 25,714°)","planific o imprimare lungă (timp, filament, verificări)"],"nevoie":["designul „v1_rigid”","fișa piesei 02","bobine PETG pline (≈ 0,5 kg pe roată)"],"casete":[{"titlu":"SSM","text":["Imprimările lungi (peste 8 ore) se lasă nesupravegheate doar dacă imprimanta are senzor de filament și oprire la supraîncălzire, iar profesorul aprobă. Nu acoperiți imprimanta."]}],"comenzi":[["Repetare polară","forma + inel-ajutor → Ctrl + D → rotire 25,714° → Ctrl + D de încă 12 ori"],["Tăiere cu găuri","tub (plin) + cilindru-gaură + cutie-gaură → grupare = arc"]],"pasi":["O spiță: tub cu rază 66,01, perete 1,6, înalt de 70. Centrul tubului NU este pe axa roții, ci la X = −8,22; Y = 11,91.","Cilindru-gaură Ø111,8, centrat pe axa roții (taie tot ce e în interiorul inelului).","Cutie-gaură 70 × 140, cu marginea din dreapta la X = −10 (taie arcul de pe partea opusă).","Grupați: rămâne un arc care pleacă din inel (R 56) și ajunge în bandă (R 77). Verificați în vederea de sus.","Repetare: spița + inelul-ajutor → Ctrl + D → rotire 25,714° → încă 12 × Ctrl + D. Rezultă 14 spițe.","Canalele benzii: cutie-gaură 3 × 3 × 62 (Z 4…66), cu centrul la 80 de axă (taie 1,5 în bandă). Cu inelul-ajutor: Ctrl + D, rotire 10°, de 35 de ori: 36 de canale.","Provocare (opțional): teșitura de 2,5 a benzii, cu un con-gaură inelar.","Grupați roata completă. Feliator: 4 pereți, 30% giroid, viteză 40 mm/s pe spițe. Notați timpul și masa. Lansați prima roată."],"fise":[{"nr":"02","nume":"Roată fără aer Ø160 × 70","info":"4 buc. pe rover · lecția 18","cote":[{"nr":"1","cota":"Diametru exterior × lățime","nominal":"Ø160 × 70","tol":"±0,5"},{"nr":"2","cota":"Banda de rulare (grosime)","nominal":"4","tol":"±0,2"},{"nr":"3","cota":"Inel interior (rază ext. / grosime)","nominal":"R56,5 / 3","tol":"±0,2"},{"nr":"4","cota":"Spițe (14×): grosime · unghi","nominal":"1,6 · 90°","tol":"±0,1"},{"nr":"5","cota":"Canale anti-alunecare (36×)","nominal":"3 × 1,5 · z 4…66","tol":"±0,3"},{"nr":"6","cota":"Disc (grosime) · 6 ferestre","nominal":"6 · Ø24 pe R37","tol":"±0,2"},{"nr":"7","cota":"Coloană (Ø × înălțime)","nominal":"Ø32 × 27","tol":"±0,2"},{"nr":"8","cota":"Găuri prindere (4×) · lamaj","nominal":"Ø3,4 pe Ø22 · Ø6,5 × 3,5","tol":"±0,15"}],"parametri":["PETG, strat 0,2","fața exterioară (discul) pe masă","4 pereți / 30% giroid · spițe la ≈ 40 mm/s","nu","21,8 h / 499 g"],"img":"img/piese/02.png"}],"control":["14 spițe egale, fără spițe dublate","Spițele pornesc din inel și intră în bandă","36 de canale","Prima roată este lansată la imprimare"],"reflectie":"Spița e un arc de cerc, nu o linie dreaptă. Ce s-ar întâmpla cu o spiță dreaptă, radială, când roata e apăsată?","iso":"2027-05-12","quiz":[{"q":"Cu ce unghi rotim fiecare dintre cele 14 spițe?","o":["25°","25,714°","30°","14°"],"a":1,"e":"360° / 14 = 25,714°."},{"q":"De ce spițele sunt arcuri de cerc, nu raze drepte?","o":["Arată mai bine","Se îndoaie elastic și amortizează; o spiță dreaptă s-ar flamba sau rupe","Consumă mai mult material","Se imprimă mai repede"],"a":1,"e":"Arcul lucrează ca un arc elastic; spița radială dreaptă ar fi rigidă și s-ar rupe la apăsare."},{"q":"Cât durează imprimarea unei roți?","o":["≈ 2 h","≈ 22 h","≈ 87 h","≈ 45 min"],"a":1,"e":"≈ 22 h pe roată; cele 4 roți ≈ 87 h, peste jumătate din timpul total."},{"q":"Ce verifici la prima spiță a roții, înainte de repetarea polară?","o":["Culoarea","Un singur arc, gros de 1,6, cu capătul interior pe inel și cel exterior în bandă","Doar înălțimea de 70","Nimic, se verifică la final"],"a":1,"e":"Punctul de control din lecția 18: o greșeală la prima spiță s-ar repeta de 14 ori."}]},{"nr":19,"titlu":"Suportul motorului NEMA 17","sapt":"S4","data":"jo 13.05.2027","ore":6,"teme":"T4","piese":"01 Suport motor NEMA 17","scop":"Modelezi suportul care prinde motorul pe placa inferioară de aluminiu: pereți groși, fața cu gaura de centrare și 4 găuri de motor, inserții M4 sus și jos.","stiu":["proiectez o piesă de rezistență (pereți groși, umplere mare)","combin găuri verticale și orizontale (picătură)","verific poziția axei față de placă (calcul de cote în lanț)"],"nevoie":["un motor NEMA 17","inserții M4","fișa piesei 01"],"casete":[{"titlu":"SSM","text":["Motorul cântărește 280 g: nu-l lăsați pe marginea mesei."]}],"comenzi":[["Plan de lucru pe fața verticală","W pe fața suportului, ca să așezați găurile orizontale direct pe ea"]],"pasi":["Pereții laterali: 2 cutii 70 × 10 × 44,8, la Y = 0…10 și 54…64.","Traversa din spate: cutie 8 × 44 × 44,8 (X 0…8, Y 10…54). Fața motorului: cutie 6 × 44 × 44,8 (X 64…70).","Gaura de centrare: picătură Ø23, orizontală (pe X), prin față, cu axa la Y = 32, Z = 22,4.","Găurile motorului: 4 picături Ø3,4 la Y = 16,5 / 47,5 și Z = 6,9 / 37,9 (pătrat de 31).","Fanta cablului prin traversă: cutie-gaură 10 × 20 × 21 (Y 22…42, Z 12…33).","Inserții M4: găuri Ø5,6, adânci de 9, jos și sus, cu axele la X = 4 și 26, Y = 5 și 59.","Ferestre de ușurare: cutie-gaură 18 × 64 × 20,8 (X 40…58, Z 12…32,8), prin ambii pereți.","Imprimați un suport: 5 pereți, 40%. Probați motorul."],"fise":[{"nr":"01","nume":"Suport motor NEMA 17","info":"4 buc. pe rover · lecția 19","cote":[{"nr":"1","cota":"Lungime × lățime × înălțime","nominal":"70 × 64 × 44,8","tol":"±0,3"},{"nr":"2","cota":"Grosime pereți laterali / față / traversă","nominal":"10 / 6 / 8","tol":"±0,2"},{"nr":"3","cota":"Gaură de centrare motor","nominal":"Ø23 (picătură)","tol":"±0,15"},{"nr":"4","cota":"Găuri motor (4×)","nominal":"Ø3,4 · entraxe 31 × 31","tol":"±0,15"},{"nr":"5","cota":"Axa motorului de la talpă","nominal":"22,4","tol":"±0,2"},{"nr":"6","cota":"Găuri inserții M4 (8×: 4 sus + 4 jos)","nominal":"Ø5,6 · adâncime 9","tol":"±0,1"},{"nr":"7","cota":"Fanta de cablu în traversă","nominal":"20 × 21","tol":"±0,3"},{"nr":"8","cota":"Ferestre de ușurare (2×)","nominal":"18 × 20,8","tol":"±0,3"}],"parametri":["PETG, strat 0,2","talpa pe masă (poziția de montaj)","5 pereți / 40%","nu (găuri „picătură”)","2,5 h / 57 g"],"img":"img/piese/01.png"}],"control":["Motorul intră cu centrarea Ø22 în gaura Ø23","Cele 4 găuri se potrivesc","Axa motorului la 22,4 de talpă"],"reflectie":"Axa roții e la 80 mm de sol. Placa inferioară e la 54,5 de sol și are 3 mm. Verificați prin calcul: unde trebuie să fie axa motorului față de talpa suportului?","iso":"2027-05-13","quiz":[{"q":"Ce pătrat formează găurile de prindere ale motorului NEMA 17?","o":["42,3 × 42,3","31 × 31","22 × 22","26 × 26"],"a":1,"e":"4 găuri Ø3,4 cu entraxe 31 × 31."},{"q":"La ce înălțime față de talpă este axa motorului (fișa piesei)?","o":["44,8","22,4","31","80"],"a":1,"e":"Fișa piesei 01: axa motorului la 22,4 mm de talpă."},{"q":"Ce setări folosim pentru suportul motorului?","o":["2 pereți, 0%","5 pereți, 40%","3 pereți, 20%","1 perete, 100%"],"a":1,"e":"Piesă de rezistență: 5 pereți, umplere 40%."}]},{"nr":20,"titlu":"Asamblarea digitală a propulsiei. Controlul pieselor","sapt":"S4","data":"vi 14.05.2027","ore":6,"teme":"T5","piese":"—","scop":"Asamblezi digital o roată completă: suport, motor (model simplificat), butuc, roată. Verifici jocurile și distanța față de sol. Controlezi piesele S4 imprimate.","stiu":["modelez un „model de gabarit” simplificat (motorul ca o cutie cu ax)","verific jocuri și distanțe într-o asamblare","completez fișa de control a pieselor de rezistență"],"nevoie":["piesele 01, 02, 03 (STL și imprimate)","un motor","șubler"],"casete":[{"titlu":"SSM","text":["Roata se rotește cu mâna doar cu motorul nealimentat."]}],"comenzi":[["Model de gabarit","motor = cutie 42,3 × 42,3 × 40 + cilindru Ø22 × 2 + ax Ø5 × 22"]],"pasi":["Modelați motorul simplificat (dimensiunile din tabelul comenzilor).","Importați suportul, butucul și roata. Asamblați: motorul în suport, butucul pe ax, roata pe butuc.","Măsurați în design: jocul roată – suport (minimum 3), jocul roată – placă și garda la sol (minimum 50).","Controlul fizic: butucul pe ax, roata pe butuc (șuruburi M3 × 30), rotire liberă.","Completați tabelul de control al propulsiei."],"fise":[],"control":["Joc roată – suport ≥ 3","Garda la sol ≥ 50","Roata nu oscilează (bătaie radială ≤ 1 mm)"],"reflectie":"Care piesă a propulsiei vi s-a părut cea mai grea de modelat? De ce?","iso":"2027-05-14","quiz":[{"q":"Cât trebuie să fie, minimum, garda la sol?","o":["30 mm","50 mm","80 mm","3 mm"],"a":1,"e":"Condiția de control: garda la sol ≥ 50 mm."},{"q":"Ce joc minim lăsăm între roată și suport?","o":["0,2 mm","3 mm","10 mm","1 mm"],"a":1,"e":"Joc roată – suport ≥ 3 mm."},{"q":"Ce este un model de gabarit?","o":["Modelul complet al motorului cu bobinaj","Un model simplificat: motorul ca o cutie cu ax","Un desen 2D","Fișierul STL al roții"],"a":1,"e":"Motorul = cutie 42,3 × 42,3 × 40 + cilindru Ø22 × 2 + ax Ø5 × 22: suficient pentru verificarea jocurilor."}]},{"nr":21,"titlu":"Caseta acumulatorului: corp și capac","sapt":"S5","data":"lu 31.05.2027","ore":6,"teme":"T4","piese":"04 Caseta acumulatorului – corp, 05 Caseta acumulatorului – capac","scop":"Modelezi caseta în care stă acumulatorul LiFePO4. Caseta intră în rover de jos, prin decupajul plăcii inferioare.","stiu":["modelez un corp cu flanșă și interior cu joc pentru acumulator","fac stâlpi pentru șuruburi autofiletante","poziționez elemente care trebuie să corespundă între două piese (capac – locaș)"],"nevoie":["acumulatorul (sau macheta lui: 132 × 72 × 34)","fișele pieselor 04 și 05"],"casete":[{"titlu":"SSM","text":["Acumulatorul nu se găurește, nu se lovește și nu se scurtcircuitează. Bornele se acoperă cu bandă izolatoare."]}],"comenzi":[["Simetrie","construiți o jumătate, apoi oglindiți (M) și grupați"]],"pasi":["Flanșa: cutie 166 × 96 × 3, Radius 6.","Corpul: cutie 153 × 83 × 39, Radius 3, centrată pe flanșă, de la Z = 3. Golul: 148 × 78, Radius 1,5, de la Z = 3.","Stâlpii capacului: 4 cutii 8 × 3 pe pereții lungi, cu axele la X = 33 și 133. Găuri Ø2,6 adânci de 10 (autofiletant M3).","Găuri pentru șnurul de tragere: Ø4,4 în flanșă, cu axele la X = 4 și 162, Y = 48.","Fante în fund (7×): 12 × 4, cu axele la X = 29, 47, … 137 (pas 18), Y = 48.","Capacul (05): 153 × 83 × 2,5, Radius 3. Găuri Ø3,4 la (26,5 / 126,5; 3 / 80). Găuri de ghidare Ø6,6 la (26,5 și 126,5; 41,5). Locașul Powerpole 8,4 × 16,4 la X = 138,3…146,7, Y = 33,3…49,7."],"fise":[{"nr":"04","nume":"Caseta acumulatorului – corp","info":"1 buc. pe rover · lecția 21","cote":[{"nr":"1","cota":"Flanșă","nominal":"166 × 96 × 3 · R6","tol":"±0,3"},{"nr":"2","cota":"Corp exterior · înălțime totală","nominal":"153 × 83 · 42","tol":"±0,3"},{"nr":"3","cota":"Interior (pentru acumulator)","nominal":"148 × 78 · R1,5","tol":"±0,2"},{"nr":"4","cota":"Stâlpi capac (4×) · găuri autofiletante","nominal":"8 × 3 · Ø2,6 × 10","tol":"±0,15"},{"nr":"5","cota":"Găuri pentru șnurul de tragere (2×)","nominal":"Ø4,4 la 79 de centru","tol":"±0,2"},{"nr":"6","cota":"Fante în fund (7×)","nominal":"12 × 4 · pas 18","tol":"±0,3"}],"parametri":["PETG, strat 0,2","flanșa pe masă","4 pereți / 30%","nu","4,5 h / 103 g"],"img":"img/piese/04.png"},{"nr":"05","nume":"Caseta acumulatorului – capac","info":"1 buc. pe rover · lecția 21","cote":[{"nr":"1","cota":"Lungime × lățime × grosime","nominal":"153 × 83 × 2,5 · R3","tol":"±0,2"},{"nr":"2","cota":"Găuri șuruburi (4×)","nominal":"Ø3,4 · entraxe 100 × 77","tol":"±0,15"},{"nr":"3","cota":"Găuri de ghidare (2×)","nominal":"Ø6,6 · entraxe 100","tol":"±0,15"},{"nr":"4","cota":"Locaș Powerpole","nominal":"8,4 × 16,4","tol":"±0,15"}],"parametri":["PETG, strat 0,2","plat","3 pereți / 20%","nu","1,5 h / 34 g"],"img":"img/piese/05.png"}],"control":["Acumulatorul intră cu joc ≤ 2 mm","Găurile capacului cad pe stâlpi","Găurile de ghidare sunt la 100 mm"],"reflectie":"Acumulatorul cântărește ≈ 0,9 kg. Ce piese și ce elemente îl țin în rover? Desenați traseul forței.","iso":"2027-05-31","quiz":[{"q":"Ce gaură folosim pentru un șurub autofiletant M3 în stâlpi?","o":["Ø3,4","Ø2,6","Ø4,0","Ø5,6"],"a":1,"e":"Ø2,5 … 2,6: șurubul își taie singur filetul în plastic."},{"q":"Ce entraxe au găurile de ghidare Ø6,6 din capac?","o":["77","100","120","153"],"a":1,"e":"Găurile de ghidare sunt la 100 mm; în ele intră știfturile conice ale locașului."},{"q":"Cum construiești rapid o piesă simetrică?","o":["Cu Ctrl + G","Construiești o jumătate, apoi oglindești (M) și grupezi","Cu Text","Cu scalare"],"a":1,"e":"Simetria cu M înjumătățește munca și garantează piese identice stânga–dreapta."}]},{"nr":22,"titlu":"Locașul acumulatorului (imprimat cu fundul în sus)","sapt":"S5","data":"mi 02.06.2027","ore":3,"teme":"T4","piese":"06 Locașul acumulatorului","scop":"Modelezi locașul fixat deasupra decupajului din placă: caseta intră în el și se centrează pe știfturi conice. Piesa se imprimă întoarsă, ca să nu aibă nevoie de suporturi.","stiu":["proiectez știfturi conice de centrare","aleg orientarea care elimină suporturile","verific potrivirea cu piesa pereche (capacul casetei)"],"nevoie":["capacul casetei (05)","fișa piesei 06"],"casete":[{"titlu":"SSM","text":["Piesele mari se desprind de pe masă doar după răcire. Nu forțați spatula."]}],"comenzi":[["Con ca știft","Cone: rază jos 2, rază sus 3, înălțime 6"]],"pasi":["Corpul: cutie 160 × 90 × 45, Radius 3. Golul: 155 × 85, Radius 1,5, de jos până la Z = 39. Tavanul rămâne de 6.","Urechile (4×): cilindri Ø10 × 45, cu axele la X = 20 și 140, Y = −3 și 93 (ies cu 8 mm în afara pereților). Găuri Ø5,6 adânci de 9, de jos.","Inserții în tavan (4×): Ø5,6 adânci de 9, de sus, la X = 35 / 125 și Y = 15 / 75.","Știfturile conice (2×): sub tavan (Z 33…39), Ø4 jos → Ø6 sus, la X = 30 și 130, Y = 45. Intră în găurile Ø6,6 ale capacului casetei.","Locașul Powerpole prin tavan: 8,4 × 16,4 la X = 141,8…150,2, Y = 36,8…53,2. Canalul cablului pe tavan: 10 × 3,5, de la locaș până la peretele Y = 0.","Imprimați întors (tavanul pe masă)."],"fise":[{"nr":"06","nume":"Locașul acumulatorului","info":"1 buc. pe rover · lecția 22","cote":[{"nr":"1","cota":"Corp: lungime × lățime × înălțime","nominal":"160 × 90 × 45 · R3","tol":"±0,3"},{"nr":"2","cota":"Gol interior · grosime tavan","nominal":"155 × 85 · 6","tol":"±0,2"},{"nr":"3","cota":"Urechi de prindere (4×)","nominal":"Ø10 · entraxe 120 × 96","tol":"±0,2"},{"nr":"4","cota":"Găuri inserții M4 jos (4×) / în tavan (4×)","nominal":"Ø5,6 × 9","tol":"±0,1"},{"nr":"5","cota":"Știfturi conice de ghidare (2×)","nominal":"Ø4 → Ø6 · h 6 · entraxe 100","tol":"±0,15"},{"nr":"6","cota":"Locaș Powerpole · canal cablu","nominal":"8,4 × 16,4 · 10 × 3,5","tol":"±0,15"}],"parametri":["PETG, strat 0,2","întors: tavanul pe masă","4 pereți / 30%","nu","6,3 h / 145 g"],"img":"img/piese/06.png"}],"control":["Știfturile intră în găurile capacului 05","Locașurile Powerpole sunt față în față","Fără suporturi la imprimare"],"reflectie":"Știfturile sunt conice, nu cilindrice. Ce avantaj au la introducerea casetei „pe orbește”, de jos?","iso":"2027-06-02","quiz":[{"q":"De ce imprimăm locașul întors, cu tavanul pe masă?","o":["Se vede mai bine","Nu mai are nevoie de suporturi","Este mai rapid cu 50%","Ca să fie mai ușor"],"a":1,"e":"Orientarea aleasă elimină zonele în consolă, deci suporturile."},{"q":"Ce avantaj au știfturile conice?","o":["Sunt mai ușoare","Centrează caseta chiar dacă intră ușor decalat, „pe orbește”","Țin acumulatorul cald","Se imprimă mai repede"],"a":1,"e":"Conul ghidează caseta spre poziția corectă când o introducem de jos."},{"q":"Ce grosime are tavanul locașului?","o":["3 mm","6 mm","9 mm","2,4 mm"],"a":1,"e":"Golul merge până la Z = 39 dintr-o înălțime de 45: tavanul are 6 mm."}]},{"nr":23,"titlu":"Zăvorul cu arc: carcasă și bolț","sapt":"S5","data":"mi 02.06.2027","ore":3,"teme":"T4","piese":"07 Zăvor – carcasă, 08 Zăvor – bolț","scop":"Modelezi zăvorul care blochează caseta: un bolț cu arc și rampă la 45°. Când caseta urcă, rampa împinge bolțul înapoi; după ce caseta trece, arcul împinge bolțul sub flanșă: „clic”.","stiu":["modelez un mecanism simplu cu piese mobile și jocuri de glisare","folosesc pana (Wedge) pentru rampe","verific cursa mecanismului"],"nevoie":["arc de compresie Ø5 × 15","inserții M3","fișele pieselor 07 și 08"],"casete":[{"titlu":"SSM","text":["Arcul comprimat poate sări: țineți-l cu degetul la montaj și purtați ochelari."]}],"comenzi":[["Pană","Wedge: rotiți-o ca panta să fie pe muchia de jos-față"],["Joc de glisare","canalul are +0,6 față de bolț (12,6 / 12)"]],"pasi":["Carcasa (07): cutie 24 × 30 × 12. Canalul bolțului: cutie-gaură 12,6 × 26,5 × 6,4 (X 5,7…18,3, Y 3,5…30, Z 2,4…8,8), deschis în față.","Fanta butonului, în fund: 6 × 9,5 (X 9…15, Y 5,5…15, prin fund). Capătul fantei limitează cursa la 4 mm.","Inserții M3: găuri Ø4,0 adânci de 7 de sus, la (4; 15) și (20; 15). Știftul arcului: cilindru Ø2,8 pe direcția Y, de la Y = 3,4 la 7, cu axa la X = 12, Z = 5,8.","Bolțul (08): corp 12 × 22 × 6 + nas 12 × 5 × 6 în față.","Rampa: pană-gaură 12 × 5 × 5 pe muchia de jos-față a nasului (urcă la 45°).","Butonul, în jos: cutie 5 × 5 × 11. Locașul arcului: gaură Ø5,2 adâncă de 8, din spate.","Imprimați 2 seturi, 100% umplere. Montați și probați: bolțul revine singur și iese 5 mm."],"fise":[{"nr":"07","nume":"Zăvor – carcasă","info":"2 buc. pe rover · lecția 23","cote":[{"nr":"1","cota":"Lungime × lățime × înălțime","nominal":"24 × 30 × 12","tol":"±0,2"},{"nr":"2","cota":"Canalul bolțului (lățime × înălțime)","nominal":"12,6 × 6,4","tol":"±0,15"},{"nr":"3","cota":"Fanta butonului în fund","nominal":"6 × 9,5","tol":"±0,15"},{"nr":"4","cota":"Găuri inserții M3 (2×)","nominal":"Ø4,0 · entraxe 16 · adânc. 7","tol":"±0,1"},{"nr":"5","cota":"Știftul arcului","nominal":"Ø2,8 × 3,6","tol":"±0,1"}],"parametri":["PETG, strat 0,2","fața de sus (spre placă) pe masă","umplere 100%","nu","0,3 h / 7 g"],"img":"img/piese/07.png"},{"nr":"08","nume":"Zăvor – bolț","info":"2 buc. pe rover · lecția 23","cote":[{"nr":"1","cota":"Lungime totală × lățime × înălțime","nominal":"27 × 12 × 16,8","tol":"±0,2"},{"nr":"2","cota":"Corp","nominal":"22 × 12 × 6","tol":"±0,1"},{"nr":"3","cota":"Nas cu rampă la 45°","nominal":"5","tol":"±0,15"},{"nr":"4","cota":"Buton (în jos)","nominal":"5 × 5 × 11","tol":"±0,2"},{"nr":"5","cota":"Locașul arcului","nominal":"Ø5,2 × 8","tol":"±0,15"}],"parametri":["PETG, strat 0,2","culcat pe o față laterală","umplere 100%","nu","0,1 h / 2 g"],"img":"img/piese/08.png"}],"control":["Bolțul alunecă fără blocare","Arcul îl readuce complet","Rampa este pe partea dinspre casetă"],"reflectie":"Ce s-ar întâmpla dacă rampa ar fi pe partea de sus a nasului?","iso":"2027-06-02","quiz":[{"q":"Ce joc are bolțul de 12 mm în canalul de 12,6?","o":["0,1 pe parte","0,3 pe parte (0,6 total)","1,2 pe parte","fără joc"],"a":1,"e":"Joc de glisare: 12,6 − 12 = 0,6, adică 0,3 pe fiecare parte."},{"q":"Unde trebuie să fie rampa de 45° a bolțului?","o":["Pe partea de sus a nasului","Pe muchia de jos-față, spre casetă","În spatele bolțului","Pe buton"],"a":1,"e":"Caseta care urcă apasă rampa și împinge bolțul înapoi; apoi arcul îl scoate sub flanșă."},{"q":"Ce umplere folosim la zăvor?","o":["0%","20%","100%","50%"],"a":2,"e":"Piese mici și solicitate: umplere 100%."}]},{"nr":24,"titlu":"Fișa procesului de imprimare. Recepția pieselor. Montajul pe șasiu","sapt":"S5","data":"jo 03.06.2027","ore":6,"teme":"T5 · T6","piese":"—","scop":"Completezi fișa procesului de imprimare pentru o piesă la alegere. Faci recepția tuturor pieselor imprimate de clasă și le montezi pe șasiul de aluminiu, după dosarul tehnic al roverului.","stiu":["documentez un proces tehnologic (fișă de proces)","fac recepția calitativă după o listă de verificare","montez subansamble după instrucțiuni"],"nevoie":["toate piesele imprimate","dosarul tehnic FM-R2 (capitolul de asamblare)","șurubelnițe, chei hexagonale, inserții, letcon"],"casete":[{"titlu":"SSM","text":["Plăcile de aluminiu au muchii tăioase: mănuși la manipulare. Șasiul se ține pe suport, nu pe genunchi."]}],"comenzi":[],"pasi":["Alegeți o piesă (alta decât colegul de echipă) și completați fișa procesului din anexa D.","Recepția: fiecare echipă verifică piesele altei echipe (verificare încrucișată) pe lista din tabelul de recepție.","Montajul inserțiilor în toate piesele (posturi de lucru cu letcon, prin rotație).","Montajul pe șasiu, pe echipe: (1) locaș + zăvoare, (2) suporturi + motoare + roți, (3) șine DIN + carcase A/B, (4) șine Picatinny + module C.","Fotografii pentru portofoliu și pentru proiectul eTwinning."],"fise":[],"control":["Fișa de proces este completată","Toate piesele au trecut recepția","Subansamblul echipei este montat"],"reflectie":"Dacă ar trebui să mai imprimați un rover, ce ați schimba în fișa de proces ca să economisiți timp?","iso":"2027-06-03","quiz":[{"q":"Ce înseamnă recepția prin verificare încrucișată?","o":["Fiecare elev își verifică singur piesele","Fiecare echipă verifică piesele altei echipe","Profesorul verifică doar o piesă","Nu se verifică nimic"],"a":1,"e":"Ochii altei echipe găsesc mai ușor abaterile pe care autorul nu le vede."},{"q":"Ce conține fișa procesului de imprimare?","o":["Doar numele piesei","Operațiile, parametrii, timpii, controlul și responsabilul","Doar fotografia","Doar costul"],"a":1,"e":"Anexa D: 10 operații, de la verificarea modelului la etichetare și predare."},{"q":"Ce montează echipa (1) pe șasiu?","o":["Șinele Picatinny","Locașul și zăvoarele","Roțile","Carcasele A/B"],"a":1,"e":"(1) locaș + zăvoare, (2) suporturi + motoare + roți, (3) șine DIN + carcase A/B, (4) șine Picatinny + module C."},{"q":"De ce partea care dă tensiunea (carcasele A și B) are conector mamă?","o":["Pentru că e mai ieftin","Contactele mamă sunt ascunse în plastic: o mufă scoasă nu poate face scurtcircuit","Ca să încapă mai multe fire","Nu contează, se poate și invers"],"a":1,"e":"Regula mamă–tată din anexa G: sursa are mamă, modulul are tată, cablul este tată–mamă."}]},{"nr":25,"titlu":"Proiectul individual. Portofoliul. Evaluarea finală","sapt":"S5","data":"vi 04.06.2027","ore":6,"teme":"T7","piese":"—","scop":"Proiectezi singur o piesă nouă pentru rover, care respectă standardele clasei: un accesoriu pentru o carcasă C sau un suport. Îți prezinți portofoliul.","stiu":["proiectez independent o piesă care respectă un standard de interfață","îmi prezint munca (3 minute) și primesc feedback","îmi evaluez progresul pe toate cele 5 săptămâni"],"nevoie":["caietul complet","portofoliul (STL-uri, fotografii, fișe)"],"casete":[{"titlu":"SSM","text":["Ordine finală în laborator: calculatoarele închise, imprimantele curățate, resturile de filament colectate separat."]}],"comenzi":[],"pasi":["Alegeți tema proiectului (exemple: față C pentru un senzor de gaz MQ-2, suport de telefon pe șina Picatinny, cârlig pentru cabluri pe șina DIN, ecuson cu logo FutureMakers).","Schiță în caiet, cu cote. Modelare în Tinkercad. Verificare cu standardele clasei.","Imprimare (dacă timpul permite; altfel, se imprimă după practică).","Prezentare de 3 minute: ce problemă rezolvă piesa, cum ați modelat-o, ce ați verificat.","Completați autoevaluarea finală și grila de notare."],"fise":[],"control":["Piesa respectă o interfață standard (C, DIN sau Picatinny)","Schița are cote","Prezentarea a fost susținută"],"reflectie":"Ce știi să faci acum, după cele 5 săptămâni, și nu știai la început? Dă trei exemple concrete.","iso":"2027-06-04","quiz":[{"q":"Ce condiție trebuie să respecte piesa din proiectul individual?","o":["Să fie cât mai mare","Să respecte o interfață standard (C, DIN sau Picatinny)","Să fie colorată","Să aibă text"],"a":1,"e":"Piesa nouă trebuie să se monteze pe rover printr-o interfață standard."},{"q":"Cât durează prezentarea proiectului?","o":["1 minut","3 minute","10 minute","o oră"],"a":1,"e":"3 minute: ce problemă rezolvă piesa, cum ai modelat-o, ce ai verificat."},{"q":"Câte puncte valorează piesele imprimate și conforme în nota finală?","o":["10","20","40","100"],"a":2,"e":"Procentul de cote conforme × 40, din totalul de 100 de puncte; nota = total / 10."}]}],"piese":[{"nr":"01","nume":"Suport motor NEMA 17","buc":4,"material":"PETG","masa":228,"ore":"10,0","lectia":19},{"nr":"02","nume":"Roată fără aer Ø160 × 70","buc":4,"material":"PETG","masa":1994,"ore":"87,2","lectia":17},{"nr":"03","nume":"Butuc de antrenare (arbore 5 mm cu plat)","buc":4,"material":"PETG","masa":24,"ore":"1,0","lectia":16},{"nr":"04","nume":"Caseta acumulatorului – corp","buc":1,"material":"PETG","masa":103,"ore":"4,5","lectia":21},{"nr":"05","nume":"Caseta acumulatorului – capac","buc":1,"material":"PETG","masa":34,"ore":"1,5","lectia":21},{"nr":"06","nume":"Locașul acumulatorului","buc":1,"material":"PETG","masa":145,"ore":"6,3","lectia":22},{"nr":"07","nume":"Zăvor – carcasă","buc":2,"material":"PETG","masa":14,"ore":"0,6","lectia":23},{"nr":"08","nume":"Zăvor – bolț","buc":2,"material":"PETG","masa":5,"ore":"0,2","lectia":23},{"nr":"10","nume":"Carcasa A (DIN)","buc":3,"material":"PETG","masa":209,"ore":"9,2","lectia":12},{"nr":"11","nume":"Capac A","buc":3,"material":"PETG","masa":73,"ore":"3,2","lectia":3},{"nr":"12","nume":"Carcasa B (DIN)","buc":2,"material":"PETG","masa":93,"ore":"4,1","lectia":11},{"nr":"13","nume":"Capac B","buc":2,"material":"PETG","masa":26,"ore":"1,1","lectia":3},{"nr":"14","nume":"Placă de montaj A – grilă","buc":2,"material":"PETG","masa":41,"ore":"1,8","lectia":6},{"nr":"15","nume":"Placă de montaj A – Arduino Mega","buc":1,"material":"PETG","masa":23,"ore":"1,0","lectia":7},{"nr":"16","nume":"Placă de montaj B – grilă","buc":2,"material":"PETG","masa":19,"ore":"0,8","lectia":6},{"nr":"17","nume":"Opritor pentru șina DIN","buc":8,"material":"PETG","masa":33,"ore":"1,4","lectia":9},{"nr":"20","nume":"Șină Picatinny 150","buc":2,"material":"PETG","masa":33,"ore":"1,5","lectia":8},{"nr":"21","nume":"Șină Picatinny 70","buc":1,"material":"PETG","masa":8,"ore":"0,3","lectia":8},{"nr":"22","nume":"Carcasa C – corp","buc":5,"material":"PETG","masa":236,"ore":"10,3","lectia":13},{"nr":"23","nume":"Carcasa C – falcă mobilă","buc":5,"material":"PETG","masa":15,"ore":"0,7","lectia":13},{"nr":"24","nume":"Capac C simplu","buc":2,"material":"PETG","masa":19,"ore":"0,8","lectia":2},{"nr":"25","nume":"Capac C pentru lidar LD19","buc":1,"material":"PETG","masa":13,"ore":"0,6","lectia":14},{"nr":"26","nume":"Capac C pentru girofar","buc":1,"material":"PETG","masa":11,"ore":"0,5","lectia":14},{"nr":"27","nume":"Capac C pentru butonul STOP","buc":1,"material":"PETG","masa":13,"ore":"0,6","lectia":14},{"nr":"28","nume":"Dom girofar (PETG roșu translucid)","buc":1,"material":"PETG roșu translucid","masa":6,"ore":"0,3","lectia":14},{"nr":"29","nume":"Față C – senzor ultrasunete HC-SR04","buc":1,"material":"PETG","masa":6,"ore":"0,3","lectia":10},{"nr":"30","nume":"Față C – cameră ESP32-CAM","buc":1,"material":"PETG","masa":9,"ore":"0,4","lectia":10},{"nr":"31","nume":"Față C ventilată (senzori de mediu)","buc":1,"material":"PETG","masa":5,"ore":"0,2","lectia":7},{"nr":"32","nume":"Față C pentru buzzer","buc":1,"material":"PETG","masa":6,"ore":"0,3","lectia":2},{"nr":"33","nume":"Față C oarbă","buc":2,"material":"PETG","masa":13,"ore":"0,6","lectia":1}],"standarde":[{"id":"m3t","element":"Gaură de trecere M3","nominal":"Ø3,4","folosit":"capace, fălci, suport motor","optiuni":["3,0","3,2","3,4","3,6"]},{"id":"m3i","element":"Gaură pentru inserție M3 (Ø ext. 4,6 × 5,7)","nominal":"Ø4,0","folosit":"carcase, butuc, zăvor","optiuni":["3,8","4,0","4,2"]},{"id":"m4i","element":"Gaură pentru inserție M4 (Ø ext. 6,3 × 8,1)","nominal":"Ø5,6","folosit":"suport motor, locaș, opritor DIN","optiuni":["5,4","5,6","5,8"]},{"id":"m3a","element":"Gaură autofiletant M3 (direct în plastic)","nominal":"Ø2,5 … 2,6","folosit":"stâlpi Mega, casetă","optiuni":[]},{"id":"dax","element":"Alezaj în D pentru arborele NEMA 17","nominal":"Ø5,2, plat la 2,1","folosit":"butuc","optiuni":["5,0","5,2","5,4"]},{"id":"joc","element":"Joc la piese care glisează","nominal":"0,2 … 0,3 pe parte","folosit":"fețe C, bolț, casetă","optiuni":[]},{"id":"per","element":"Grosime minimă de perete","nominal":"1,6 (4 perimetre × 0,4)","folosit":"dom, spițe","optiuni":[]},{"id":"orz","element":"Gaură orizontală","nominal":"formă de picătură, vârful în sus","folosit":"suport motor, carcase","optiuni":[]}],"interfete":[["Șina DIN","EN 60715, TS35 × 7,5","lățime 35, flanșe 5 × 1; cârligul: deschidere între buze 29, fanta 1,25"],["Șina Picatinny","MIL-STD-1913 (profil compatibil)","lățime corp 15,6, max. 21,2, canale 5,23 × 3 la pas 10,01"],["Butonul de oprire de urgență","ISO 13850","buton roșu pe fond galben, gaură Ø22 + canal anti-rotire"],["Conectorul acumulatorului","Anderson Powerpole PP15/45","locaș 8,4 × 16,4 pentru o pereche de carcase"],["Inserții filetate la cald","M3 și M4 (alamă)","montaj cu letconul la 230–240 °C, 0,2 sub suprafață"]],"teme":[["T1","Securitatea și sănătatea în muncă în laboratorul CAD și la imprimanta 3D","3","L1"],["T2","Modelare de bază: forme, dimensiuni, găuri, aliniere, riglă, repetare","18","L1–L3"],["T3","Imprimarea 3D: imprimanta, feliatorul, materiale, parametri","6","L4, L5, L18"],["T4","Modelare intermediară: grile, profile standardizate, corpuri goale, piese de revoluție, repetare polară, mecanisme","78","L6–L14, L16–L19, L21–L23"],["T5","Control dimensional, asamblare digitală și fizică","18","L5, L15, L20, L24"],["T6","Documentația tehnică: schiță după model, fișa procesului","6","L10, L24"],["T7","Proiect individual, portofoliu, evaluare finală","3 + 18 recuperate","L25"]],"rezultate":{"Cunoștințe":["formele de bază și operațiile Tinkercad (gaură, grupare, aliniere, oglindire, repetare)","legătura dintre desenul tehnic și modelul 3D","tehnologia FDM: straturi, pereți, umplere, suporturi","materialele PLA, PETG, TPU","ajustaje, jocuri și toleranțe pentru piese imprimate","interfețe standardizate: șina DIN EN 60715, Picatinny MIL-STD-1913"],"Abilități":["modelez piese după desen, după fișă tehnică și după schiță","poziționez exact cu rigla și alinierea","pregătesc imprimarea în feliator","controlez piesele cu șublerul și decid conformitatea","montez inserții filetate și asamblez subansamble","completez fișa procesului de imprimare"],"Atitudini":["respect regulile SSM în laboratorul CAD și la imprimantă","lucrez ordonat și documentez ce fac","colaborez în echipă și verific munca colegilor","accept feedback-ul și îmi corectez modelul","folosesc responsabil materialul și energia"]},"ssm":[["Laboratorul CAD",["Postura: spatele drept, ecranul la nivelul ochilor, picioarele pe podea.","Regula 45 / 5: după 45 de minute la ecran, 5 minute de pauză pentru ochi.","Cablurile nu trec prin zona de circulație. Nu se mănâncă și nu se bea lângă calculatoare.","Laptopurile se transportă închise, cu ambele mâini."]],["Imprimanta 3D",["Duza ajunge la 240 °C, masa la 80 °C. Nu le atingeți în timpul lucrului și imediat după.","Piesa se scoate după ce masa se răcește sub 35 °C. Spatula se mișcă dinspre corp spre exterior.","Imprimanta stă într-o încăpere aerisită. Nu stați aplecat deasupra ei.","Imprimările lungi rămân nesupravegheate doar cu aprobarea profesorului, dacă imprimanta are senzor de filament și protecție la supraîncălzire.","Orice zgomot, miros de ars sau fum: STOP din meniu, apoi anunțați profesorul."]],["Inserții filetate și letcon",["Doar sub supravegherea profesorului. Mănuși și ochelari de protecție.","Letconul stă doar în suport. Nu-l lăsați pe masă.","Inserția se apasă vertical, fără răsucire."]],["Montaj și unelte",["Plăcile de aluminiu au muchii tăioase: mănuși.","Cleștele de tăiat filament se folosește cu tăișul spre masă.","Arcurile comprimate pot sări: ochelari.","Motoarele și acumulatorul se probează doar nealimentate, cu acordul profesorului."]],["Ordine și mediu",["Resturile de filament și piesele rebutate se colectează separat (se reciclează).","La plecare: calculatoarele închise, imprimantele curățate, uneltele la locul lor."]]],"reguliFisiere":["Numele designului: FMR2_<nr. piesă>_<nume scurt>_<Nume>, de exemplu FMR2_12_carcasa_B_Ionescu.","Origine: rigla în colțul din stânga-față-jos al piesei. X spre dreapta, Y spre spate, Z în sus. La piesele rotunde (butuc, roată), rigla stă în centru.","Unitatea de măsură: mm; Snap Grid = 0,1 mm.","Piesa se modelează în poziția de imprimare, cu fața care stă pe masă jos.","Fișierele STL se salvează în dosarul echipei: Echipa_X/S1 … S5/. Doar modelul validat de profesor merge la imprimantă."],"anexe":{"comenzi":[["Rotesc vederea","buton dreapta + tragere"],["Deplasez vederea","Shift + buton dreapta"],["Zoom","rotița / + și −"],["Încadrez selecția","F"],["Riglă","R"],["Notă pe planul de lucru","N"],["Plan de lucru pe o față","W"],["Las forma pe planul de lucru","D"],["Mut pe X / Y","săgeți (Shift = ×10)"],["Mut pe Z","Ctrl + săgeată sus/jos"],["Rotire în pași de 45°","Shift în timpul rotirii"],["Grupez","Ctrl + G"],["Degrupez","Ctrl + Shift + G"],["Aliniez","L"],["Oglindesc","M"],["Duplic și repet","Ctrl + D"],["Copiez / lipesc","Ctrl + C / Ctrl + V"],["Ascund / arăt tot","Ctrl + H / Ctrl + Shift + H"],["Blochez / deblochez","Ctrl + L"],["Selectez tot","Ctrl + A"],["Anulez / refac","Ctrl + Z / Ctrl + Y"],["Dublez trăgând","Alt + tragere"]],"forme":[["Cutie (Box)","Radius (rotunjirea colțurilor), Steps","plăci, carcase, canale, fante"],["Cilindru (Cylinder)","Sides (laturi), Bevel","găuri, stâlpi, bosaje, butuc"],["Tub (Tube)","Radius, Wall Thickness, Sides","inelele roții, spițele, inelul girofarului"],["Con (Cone)","Base radius, Top radius, Height","găuri înecate, știfturi, domul"],["Poligon (Polygon)","Sides = 6, Radius","locașul piuliței M3"],["Pană (Wedge)","dimensiuni","rampa zăvorului"],["Text","Text, font, înălțime","marcaje pe șablon și pe piese"]],"retete":["Corp gol: cutie plină − cutie-gaură, ridicată cu grosimea fundului.","Lamaj: gaură Ø3,4 de sus până jos + gaură Ø6 de 1,6 sus.","Cap înecat: gaură + con-gaură (rază mică jos, rază mare sus).","Picătură: cilindru orizontal + pătrat cu latura egală cu raza, rotit 45°, colțul de jos în centru.","Alezaj în D: cilindru − cutie (planul la 2,1 de axă), grupat și făcut gaură.","Repetare polară: forma + inel-ajutor centrat pe axă → Ctrl + D → rotire cu 360°/n → Ctrl + D de n − 2 ori."],"materiale":[["PLA","200–215","55–60","ușor de imprimat, rigid, se înmoaie la ≈ 55 °C","probe, plăci de montaj, șablonul E1"],["PETG","230–245","75–85","tenace, rezistă la căldură (≈ 75 °C) și la umezeală, puțin elastic","aproape toate piesele"],["TPU 95A","220–235","40–60","elastic, ca un cauciuc; se imprimă încet","opțional: benzi de rulare, tampoane"]],"parametri":[["Înălțimea stratului","0,2 mm","mai mic = mai fin, dar mai lent"],["Pereți (perimetre)","3 (piese de rezistență: 4–5)","rezistența vine mai ales din pereți"],["Umplere (infill)","20% (rezistență: 40–100%)","structura din interior"],["Suporturi","nu (piese proiectate fără)","susțin zonele în consolă"],["Răcire","PETG: 30–50%","prea multă răcire: straturi slab lipite"],["Viteză","40–60 mm/s","spițele roții: 40 mm/s"]],"defecte":[["Piesa se dezlipește de pe masă","masă murdară sau nenivelată, prima viteză prea mare","curățați cu alcool izopropilic, nivelați, lipici, „brim” de 5 mm"],["Colțurile se ridică (warping)","răcire bruscă, curent de aer","ușile închise, masa mai caldă, rotunjiri la colțuri"],["Fire subțiri între găuri (stringing)","retragere insuficientă, temperatură mare","retragere +0,5 mm, duza −5 °C"],["Găuri mai mici decât în model","contracție, cerc din segmente","standardele clasei (șablonul E1), mai multe laturi la cilindru"],["Straturi deplasate","curea slăbită, piesă lovită de duză","verificați curelele; „Z-hop” la deplasări"],["Pereți cu goluri (subextrudare)","duză înfundată, filament umed","curățați duza, uscați filamentul (PETG: 65 °C, 4 h)"]],"ajustaje":[["Piesă care trebuie să alunece","0,2–0,3 pe parte","fața C în canale, bolțul zăvorului"],["Piesă care intră strâns, cu mâna","0,1 pe parte","domul pe inelul de Ø40"],["Gaură pentru un corp rotund cumpărat","+0,3 … +0,6 la diametru","traductoarele HC-SR04: Ø16 → Ø16,6"],["Gaură de trecere pentru șurub","+0,4 la diametru","M3 → Ø3,4; M4 → Ø4,5"],["Piesă care se prinde pe un profil metalic","0,2 pe parte","cârligul DIN, fălcile Picatinny"]],"insertii":[["M3","4,6 × 5,7","Ø4,0","7","230–240 °C (PETG)"],["M4","6,3 × 8,1","Ø5,6","9","230–240 °C (PETG)"]],"montajInsertie":["Letcon cu vârf pentru inserții, la temperatura din tabel.","Inserția se așază dreaptă pe gaură, cu partea îngustă în jos.","Apăsați vertical, ușor, fără răsucire, până la 0,2 sub suprafață.","Țineți piesa 10 s să se răcească. Verificați cu un șurub."],"proces":["Verificarea modelului (cote, standarde)","Exportul STL","Feliere: orientare, pereți, umplere, suporturi","Pregătirea imprimantei: curățare, nivelare, filament","Imprimarea și verificarea primului strat","Răcirea și scoaterea piesei","Curățarea (fire, „brim”)","Montajul inserțiilor","Controlul dimensional","Etichetarea și predarea"],"glosar":[["ajustaj","fit"],["aliniere","align"],["alezaj în D","D-bore"],["bosaj","boss"],["carcasă","housing, enclosure"],["cârlig","hook, clip"],["con","cone"],["cotă","dimension"],["cutie","box"],["desen tehnic","technical drawing"],["falcă","jaw"],["fantă","slot"],["feliator","slicer"],["flanșă","flange"],["gaură de trecere","clearance hole"],["gaură înecată","countersunk hole"],["grilă de găuri","hole grid"],["grupare","group"],["imprimantă 3D","3D printer"],["inserție filetată","heat-set insert"],["joc","clearance"],["lamaj","counterbore"],["masa imprimantei","print bed"],["nervură","rib"],["oglindire","mirror"],["pană","wedge"],["perete","wall"],["picătură (gaură)","teardrop hole"],["piuliță prizonieră","captive nut"],["primul strat","first layer"],["riglă","ruler"],["roată fără aer","airless / non-pneumatic tire"],["spiță","spoke"],["stâlp","standoff, post"],["strat","layer"],["șasiu","chassis"],["șină","rail"],["șubler","caliper"],["toleranță","tolerance"],["tub","tube"],["umplere","infill"],["vedere","view"],["zăvor","latch"]],"surse":["Autodesk, Tinkercad Support (autodesk.com/support) și „Official Guide to Tinkercad Classrooms” din Help Center.","Tinkercad, Keyboard shortcuts (fișa oficială PDF).","Dosarul tehnic al roverului FM-R2 (catedra Mecanică, 2026): cote, materiale, calcule, asamblare.","SR EN 60715: Dimensiunile aparatajului de joasă tensiune. Montarea pe șine.","MIL-STD-1913: Dimensioning of Accessory Mounting Rail.","SR EN ISO 13850: Securitatea mașinilor. Funcția de oprire de urgență."]},"criterii":[{"id":"C1","nume":"Precizia modelului","S":"cotele principale sunt corecte; unele detalii lipsesc sau sunt greșite","B":"toate cotele sunt corecte; abateri mici doar la detalii","E":"toate cotele sunt exacte și verificate cu rigla; fără forme inutile"},{"id":"C2","nume":"Metoda în Tinkercad","S":"ajung la formă cu ajutor; modelul se modifică greu","B":"folosesc singur găuri, grupare, aliniere, repetare","E":"aleg cea mai simplă metodă; modelul se modifică ușor; ajut colegii"},{"id":"C3","nume":"Pregătirea imprimării","S":"aplic setările clasei cu ajutor","B":"aleg singur orientarea și setările, fără suporturi inutile","E":"îmi justific alegerile; estimez timpul și materialul; previn defectele"},{"id":"C4","nume":"Controlul piesei","S":"măsor cotele principale","B":"măsor toate cotele din fișă, calculez abaterile, decid conformitatea","E":"găsesc cauza abaterilor și corectez modelul"},{"id":"C5","nume":"Documentare, SSM, echipă","S":"caiet completat parțial; respect SSM după atenționare","B":"caiet complet; respect SSM","E":"caiet complet și îngrijit; respect SSM fără atenționări; colaborez activ"}],"faze":[{"nume":"Informare","intrebare":"Ce trebuie să fac?","text":"Citesc fișa piesei și comenzile noi."},{"nume":"Planificare","intrebare":"În ce ordine construiesc?","text":"Împart piesa în forme simple și stabilesc ordinea."},{"nume":"Decizie","intrebare":"Ce metodă aleg?","text":"Aleg metoda și setările de imprimare. Verific planul cu profesorul."},{"nume":"Execuție","intrebare":"Lucrez după plan.","text":"Modelez, export STL, imprim."},{"nume":"Control","intrebare":"Iese cum trebuie?","text":"Verific modelul cu rigla și piesa cu șublerul."},{"nume":"Evaluare","intrebare":"Ce schimb data viitoare?","text":"Mă autoevaluez S / B / E, primesc feedback, notez un lucru concret de schimbat."}],"nota":[["Piesele (model propriu, măsurare, piesa echipei)","modelul propriu: % cote corecte în Tinkercad × 20; măsurarea: % cote repartizate măsurate corect (≤ 0,05 mm) × 10; piesa echipei: % cote conforme ale pieselor imprimate de echipă × 10",40],["Punctajul săptămânal","media punctajelor lecțiilor (max. 15) × 4/3 → max. 20 pe săptămână; se face media celor 5 săptămâni",20],["Fișa procesului de imprimare","lecția 24, anexa D",10],["Proiectul individual","lecția 25: piesa, schița, prezentarea",10],["Caietul și portofoliul","completare, ordine, fișierele STL și fotografiile",10],["Din oficiu","",10]]};
